const WIKIA = "https://static.wikia.nocookie.net/hotwheels/images/";
const WIKIA_MGT = "https://static.wikia.nocookie.net/minigt/images/";
const WIKIA_TOM = "https://static.wikia.nocookie.net/tomica6057/images/";


const TOMYTEC_IMG = "https://minicar.tomytec.co.jp/common/api/image.php?jancode=";
function remoteSrc(d){
  if(!d.i) return "";
  if(d.i.slice(0,2) === "~m") return WIKIA_MGT + d.i.slice(2);
  if(d.i.slice(0,2) === "~t") return WIKIA_TOM + d.i.slice(2);
  if(d.i.slice(0,2) === "~j") return TOMYTEC_IMG + d.i.slice(2) + "&num=1";
  if(d.i.charAt(0) === "~") return WIKIA + d.i.slice(1);
  return /^https?:/.test(d.i) ? d.i : IMGBASE + d.i;
}



function unpackCat(e){
  const n = e.n, out = new Array(n);
  for(let i=0;i<n;i++) out[i] = {};
  for(const f of e.f){
    const c = e.c[f], v = c.v, d = c.d, x = c.x, m = c.m;
    if(x){
      if(d){ for(let j=0;j<x.length;j++) out[x[j]][f] = d[v[j]]; }
      else  { for(let j=0;j<x.length;j++) out[x[j]][f] = v[j]; }
    } else if(m){
      const gap = new Set(m);
      for(let j=0;j<n;j++){ if(gap.has(j)) continue; out[j][f] = d ? d[v[j]] : v[j]; }
    } else {
      if(d){ for(let j=0;j<n;j++) out[j][f] = d[v[j]]; }
      else  { for(let j=0;j<n;j++) out[j][f] = v[j]; }
    }
  }
  return out;
}


