const DEST_GROUPS = [
  ["Yours",         ["own", "order", "want", "dupe"]],
  ["The catalogue", ["all", "miss", "buy", "exc"]],
  ["The figures",   ["value", "stats", "badge"]],
  ["Collectors",    ["club", "news"]]
];


const DEST_UNLISTED = [
  {v:"me", t:"Profile", s:"Who this collector is", c:"var(--b-schuco)",
   i:'<circle cx="12" cy="8.4" r="3.8"/><path d="M4.6 20c0-3.6 3.3-5.8 7.4-5.8s7.4 2.2 7.4 5.8"/>'}
];


function curView(){
  if(typeof view!=="undefined" && view) return view;
  const b=$("#tabs").querySelector("button.on"); return b?b.dataset.v:"all";
}
function setView(v){
  const b=$("#tabs").querySelector(`[data-v="${v}"]`);
  if(b) b.click();
}


function destCounts(){
  const c={all:0,own:0,order:0,want:0,buy:0,miss:0,dupe:0,exc:0};
  for(let i=0;i<DATA.length;i++){
    const d=DATA[i];
    if(!isRelease(d)) continue;
    c.all++;
    if(isOwned(d)) c.own++; else if(isIncoming(d)) c.order++;
    if(d.w&&!d.o) c.want++;
    if(d.sh&&d.sh.length) c.buy++;
    if(!d.o) c.miss++;
    if(d.o&&qtyOf(d)>1) c.dupe++;
    if(d.ex||d.bond) c.exc++;
  }
  

  if(typeof badgeCount==="function"){ const n=badgeCount(); if(n) c.badge=n; }
  return c;
}


function drawerVisible(){
  return (typeof matchMedia==="function" && matchMedia("(min-width:1280px)").matches) || drawerOpen;
}
function paintNav(force){
  const box=document.getElementById("drnav"); if(!box) return;
  if(!force && !drawerVisible()){ NAV_STALE=true; return; }
  NAV_STALE=false;
  const v=curView(), counts=destCounts();
  const byV = {}; DEST.forEach(x => { byV[x.v] = x; });
  const row = x => {
    const n=(x.v in counts)?counts[x.v]:null;
    

    const sub = (x.v === "all" && launch164()) ? "Every 1:64 release on file" : x.s;
    return `<button type="button" class="dr-item${x.v===v?" on":""}" data-v="${x.v}">
      <span class="ic" style="color:${x.c}"><svg viewBox="0 0 24 24">${x.i}</svg></span>
      <span class="lb"><b>${x.t}</b><i>${n===null?sub:n.toLocaleString()+" · "+sub}</i></span>
      ${x.v===v?'<span class="flag">HERE</span>':""}</span></button>`;
  };
  const placed = new Set();
  let html = "";
  for(const [head, vs] of DEST_GROUPS){
    const rows = vs.map(k => byV[k]).filter(Boolean);
    if(!rows.length) continue;
    rows.forEach(x => placed.add(x.v));
    html += `<p class="dr-sec">${head}</p>` + rows.map(row).join("");
  }
   
  const rest = DEST.filter(x => !placed.has(x.v));
  if(rest.length) html += `<p class="dr-sec">More</p>` + rest.map(row).join("");
  box.innerHTML = html;
}
let NAV_STALE=true;
 
function paintDrawerCard(force){
  if(!force && !drawerVisible()){ NAV_STALE=true; return; }
  const cur=document.getElementById("drcur"); if(cur) cur.textContent=(typeof CUR!=="undefined"?CUR:"GBP");
  const paid=document.getElementById("drpaid"), cnt=document.getElementById("drcount");
  if(!paid||!cnt) return;
  const own=ownedIn();
  const spent=own.reduce((s,d)=>s+paidReceipt(d),0);
  const pieces=piecesIn(own);
  paid.textContent=spent?priv(spent):"—";
  const k=document.querySelector(".dr-card-k");
  if(k) k.innerHTML='Total paid · <b>'+(typeof CUR!=="undefined"?CUR:"GBP")+'</b>';
  cnt.textContent=own.length.toLocaleString()+" cars · "+pieces.toLocaleString()+" pieces";
  const note=document.getElementById("drnote");
  if(note) note.textContent="Brand totals overlap on purpose: a release sold under two names is one car, counted once overall.";
}
let drawerOpen=false, _drawerReturn=null;
function openDrawer(){
  drawerOpen=true; paintNav(true); paintDrawerCard(true);
  _drawerReturn=document.activeElement;
  document.getElementById("scrim").hidden=false;
  document.getElementById("drawer").classList.add("on");
  document.getElementById("navbtn").setAttribute("aria-expanded","true");
  document.body.style.overflow="hidden";
  const f=document.querySelector("#drnav .dr-item"); if(f) f.focus();
}
function closeDrawer(){
  if(!drawerOpen) return;
  drawerOpen=false;
  document.getElementById("scrim").hidden=true;
  document.getElementById("drawer").classList.remove("on");
  document.getElementById("navbtn").setAttribute("aria-expanded","false");
  document.body.style.overflow="";
  if(_drawerReturn&&_drawerReturn.focus) _drawerReturn.focus();
  _drawerReturn=null;
}
document.getElementById("navbtn").onclick=()=>{ drawerOpen?closeDrawer():openDrawer(); };
document.getElementById("scrim").onclick=closeDrawer;
document.getElementById("drnav").onclick=e=>{
  const b=e.target.closest(".dr-item"); if(!b) return;
  setView(b.dataset.v); closeDrawer();
};
document.getElementById("drport").onclick=()=>{ setView("value"); closeDrawer(); };
document.getElementById("drscan").onclick=()=>{ closeDrawer(); $("#scanbtn").click(); };
document.getElementById("drset").onclick=()=>{ closeDrawer(); setTimeout(()=>$("#skinbtn").click(),60); };
