document.getElementById("empty").onclick=e=>{
  const b=e.target.closest("[data-empty]"); if(!b) return;
  const w=b.dataset.empty;
  if(w==="q"||w==="all"){
    activeFilters().filter(f=>w==="q"?f.k==="q":true).forEach(f=>f.clear());
  }
  if(w==="brand"){ brand="__all"; line="__all"; }
  if(w==="dir"){ setView("all"); return; }
  if(w==="missing"){
    

    const typed = (q||"").trim();
    const looksLikeCode = /^[a-z]{2,6}[\s._-]*\d{2,6}[a-z0-9-]*$/i.test(typed);
    const pre = {};
    if(typed) pre[looksLikeCode ? "product_code" : "model"] = typed;
    if(brand && brand !== "__all") pre.maker = brand;
    

    const _ls = (typeof LINE_SCALE === "object" && LINE_SCALE)
                ? LINE_SCALE[line !== "__all" ? line : brand] : "";
    if(_ls) pre.scale = String(_ls).replace("/", ":");
    if(typeof openMissing === "function") openMissing(pre);
    return;
  }
  recount(); render(); paintFilters();
};

