function forgetScopeChrome(){ _scopeSig = ""; }
let _hayCache = new WeakMap();


let _numCache = new WeakMap();


let _hayWarmed = false;
function clearSearchCache(){ _hayCache = new WeakMap(); _hayWarmed = false;
  

  _numCache = new WeakMap();
  

  

  _scopeGen = (_scopeGen || 0) + 1;
  

  if(typeof clearBadgeCache==="function") clearBadgeCache();
  if(typeof scheduleBadgeCheck==="function") scheduleBadgeCheck();
}


function _hayFor(d){
  let hay = _hayCache.get(d);
  if(hay === undefined){
    let s = "";
    const add = v => { if(v) s += "\u0000" + v; };
    add(d.t); add(d.n); add(d.x); add(d.m); add(d.br); add(d.src); add(d.note);
    add(d.col); add(d.tn); add(d.cb); add(d.ev); add(d.fam);
    

    add(d.jp); add(d.jan);
    

    if(d.ms){
      add(d.ms.driver); add(d.ms.builder); add(d.ms.team); add(d.ms.chassis);
      add(d.ms.series); add(d.ms.event); add(d.ms.livery);
      

      for(const who of (d.ms.crew || [])) add(who);
      for(const also of (d.ms.event_also || [])) add(also);
      add(d.ms.result); add(d.ms.role);
      if(d.ms.season) s += "\u0000" + d.ms.season;
      if(d.ms.no != null) s += "\u0000#" + d.ms.no + "\u0000no." + d.ms.no;
    }
    

    if(Array.isArray(d.hwa) && typeof attrDef === "function")
      for(const c of d.hwa){
        const a = attrDef(c);
        if(a){ add(a.lab); add(a.short); }
      }
    

    if(typeof segOf === "function"){
      const _sg = segOf(d);
      if(_sg && typeof segName === "function") add(segName(_sg));
    }
     
    const _sc = scaleOf(d).s;
    if(_sc) s += "\u0000" + _sc + "\u0000" + _sc.replace(":", "/");
    if(d.pnum) s += "\u0000no." + d.pnum;
    const bs = brandsOf(d);
    for(let i = 0; i < bs.length; i++) s += "\u0000" + bs[i];
    hay = s.toLowerCase();
    _hayCache.set(d, hay);
  }
  return hay;
}


let _qPlan = null;
function queryPlan(){
  if(_qPlan && _qPlan.raw === q) return _qPlan;
  const ql = (q || "").trim().toLowerCase();
  

  const code = ql.match(/^(mgt|mgts|khmg|qz|mgtac|bbr|t64g|t64r|t64p|t64t|t64s|t64mc|t64k|t64|cwb64)?[\s._\-]*(?:tl)?0*(\d{1,5})$/);
  

  const canon = (() => {
    const u = ql.toUpperCase().replace(/\s+/g, "");
    const pad = n => String(parseInt(n, 10)).padStart(3, "0");
    let m;
    if((m = u.match(/^PR-?640-?(\d{1,4})$/))) return "PR640" + pad(m[1]);
    if((m = u.match(/^PR-?64-(\d{1,4})$/)))   return "PR640" + pad(m[1]);
    if((m = u.match(/^PRDC-?(\d{1,4})$/)))    return "PRDC"  + pad(m[1]);
    if((m = u.match(/^PRE-?(\d{2,4})$/)))     return "PRE"   + pad(m[1]);
    if((m = u.match(/^PRT-?(\d{2,4})$/)))     return "PRT"   + pad(m[1]);
    if((m = u.match(/^(?:XCT-?)?([A-Z]{1,3}\d{1,3}-\d{1,3})$/))) return "XCT-" + m[1];
    return null;
  })();
  const qa = ql.replace(/[^a-z0-9]/g, "");
  const plan = {raw: q, ql, code: null, canon, qa,
                 
                barcode: /^[0-9]{8,14}$/.test(qa) ? qa.replace(/^0+/, "") : null,
                numSearch: qa.length >= 4};
  if(code){
    const want = +code[2];
    plan.code = {want, pre: code[1] || null,
                 

                 asWord: (!code[1] && String(want).length >= 2)
                   ? new RegExp("(^|[^0-9a-z])" + want + "(?![0-9])", "i") : null};
  }
  

  if(typeof CODE_SEEN === "object" && CODE_SEEN && P_ALIAS_OK(plan)){
    const t = CODE_SEEN[plan.qa];
    if(t){ plan.seenAs = String(t).toLowerCase().replace(/[^a-z0-9]/g, ""); plan.seenFor = t; }
  }
  _qPlan = plan;
  return plan;
}

 
function P_ALIAS_OK(plan){ return plan.qa && plan.qa.length >= 4; }

function _numFor(d){
  let n = _numCache.get(d);
  if(n === undefined){
    n = String(d.n || "").toLowerCase().replace(/[^a-z0-9]/g, "");
    _numCache.set(d, n);
  }
  return n;
}

function matchesQ(d){
  if(!q) return true;
  const P = queryPlan(), ql = P.ql;
  if(P.code){
    const want = P.code.want, pre = P.code.pre;
    if(d.b === want && (!pre || (d.n || "").toLowerCase().startsWith(pre))) return true;
    

    if(String(d.yr || "") === ql || String(d.cyr || "") === ql) return true;
    
    
    if(pre && _numFor(d).includes(P.qa)) return true;
    

    if(P.seenAs && _numFor(d) === P.seenAs) return true;
    if(pre || !P.code.asWord) return false;
    if(P.code.asWord.test(d.t || "")) return true;
    if(P.code.asWord.test(d.m || "")) return true;
    return false;
  }
  if(P.canon && String(d.n).toUpperCase() === P.canon) return true;
  

  if(P.numSearch && _numFor(d).includes(P.qa)) return true;
   
  if(P.seenAs && _numFor(d) === P.seenAs) return true;
  

  if(_hayFor(d).includes(ql)) return true;
  

  if(P.barcode !== null){
    const qa = P.qa, bare = P.barcode;
    if((d.bcs || []).some(c => { const s = String(c).replace(/\D/g, "");
                                 return s === qa || s.replace(/^0+/, "") === bare; })) return true;
    if(typeof BARCODES === "object" && BARCODES){
      for(const t of [qa, qa.padStart(13, "0"), bare])
        if(BARCODES[t] === d.n) return true;
    }
  }
  return (d.hand||"").toLowerCase()===ql
      ||(d.p||"").toLowerCase()===ql||(d.fs||"")===q
      ||String(d.yr||"")===q||String(d.cyr||"")===q
      ||(d.iss||[]).some(i=>("-"+i.s).toLowerCase()===ql||(i.s||"").toLowerCase()===ql);
}
function subset(){
  let a=DATA.filter(inLine);
  

  a=a.filter(d=>!heldBack(d));
  if(!showCanc) a=a.filter(d=>!d.xc);
  

  if(noPreowned) a=a.filter(d=>!Array.isArray(d.hwc)||!d.hwc.length);
  

  if(noBoxes) a=a.filter(d=>!d.k);
  

  if(view==="own") a=a.filter(isOwned);
  else if(view==="order") a=a.filter(isIncoming);
  else if(view==="want") a=a.filter(d=>d.w>0&&!d.o);
  else if(view==="miss") a=a.filter(d=>!d.o);
  else if(view==="buy") a=a.filter(d=>d.sh.length&&!d.o);
  else if(view==="dupe") a=a.filter(d=>qtyOf(d)>1&&isRelease(d));
  

  else if(view==="exc") a=a.filter(d=>isRelease(d) && (excGroup==="007" ? d.bond : (d.ex && (!excGroup || d.ex.c===excGroup))));
  if(marque) a=a.filter(d=>d.m===marque);
  if(relOnly) a=a.filter(d=>d.s===1);
  if(chaseOnly) a=a.filter(d=>copiesOf(d).some(c=>/chase/i.test(c.x||"")));
  if(chaseMade) a=a.filter(d=>d.chase);
  

  if(chaseHunt) a=a.filter(d=>d.chase && d.o===1 &&
    !copiesOf(d).some(c=>/chase/i.test(c.x||"")));
  

  if(collabOnly) a=a.filter(d=>d.cb || brandsOf(d).length>1);
  if(scalePick.size) a=a.filter(inScale);
  if(q) a=a.filter(matchesQ);
  if(view==="want" && sort==="num") return [...a].sort((x,y)=>(y.w||0)-(x.w||0)
    ||((x.so!=null?x.so:x.b)||1e15)-((y.so!=null?y.so:y.b)||1e15));
  

  

  const NONUM = 1e15;
  const sk=d=>{ const v=(d.so!=null?d.so:d.b); return (v==null||v===0)?NONUM:v; };
  const skd=d=>{ const v=(d.so!=null?d.so:d.b); return (v==null||v===0)?-NONUM:v; };
  

  

  const _rankOf = {};
  const rank=d=>{
    const br = d.br;
    let r = _rankOf[br];
    if(r === undefined){
      const i = LINE_ORDER.indexOf(br);
      r = _rankOf[br] = rangeIsForeign(d) ? LINE_ORDER.length + 1
                      : (i < 0 ? LINE_ORDER.length : i);
    }
    return r;
  };
  const s={num:(x,y)=>rank(x)-rank(y)||sk(x)-sk(y)||x.n.localeCompare(y.n),
    numd:(x,y)=>rank(x)-rank(y)||skd(y)-skd(x)||y.n.localeCompare(x.n),

    name:(x,y)=>((x.t||"\uffff").localeCompare(y.t||"\uffff")),
    price:(x,y)=>(x.sh.length?Math.min(...x.sh.map(z=>z[1])):1e9)-(y.sh.length?Math.min(...y.sh.map(z=>z[1])):1e9),
    val:(x,y)=>(y.v||0)-(x.v||0),
    

    rare:(x,y)=>(y.rr==null?-1:y.rr)-(x.rr==null?-1:x.rr)||x.n.localeCompare(y.n),
    common:(x,y)=>(x.rr==null?101:x.rr)-(y.rr==null?101:y.rr)||x.n.localeCompare(y.n),
    new:(x,y)=>relKey(y)-relKey(x),
    old:(x,y)=>relKey(x)-relKey(y)}[sort];
  return [...a].sort(s);
}



function setProgress(d){
  const parts=(d.parts||[]).map(n=>byNum.get(n)).filter(Boolean);
  if(!parts.length) return null;
  return {have:parts.filter(p=>p.o===1).length, coming:parts.filter(p=>p.o===2).length, n:parts.length};
}
 
function setsOf(d){
  return DATA.filter(x=>x.k && (x.parts||[]).includes(d.n));
}


function hl(text){
  const t=esc(text||"");
  const s=(q||"").trim();
  if(s.length<2) return t;
  try{
    const re=new RegExp("("+s.replace(/[.*+?^${}()|[\]\\]/g,"\\$&")+")","ig");
    return t.replace(re,"<mark>$1</mark>");
  }catch(_){ return t; }
}



 
const RAR_BANDS = ["Common","Uncommon","Scarce","Rare","Very Rare","Exceptional"];


const RAR_EDGES = [0,20,40,60,80,95];
const RAR_CONF  = ["Low","Medium","High"];
function rarBand(sc){
  let i = 0;
  for(let k = 0; k < RAR_EDGES.length; k++) if(sc >= RAR_EDGES[k]) i = k;
  return RAR_BANDS[i];
}


function rarityOf(d){
  if(!d || d.rr == null) return null;
  return { s: d.rr, b: rarBand(d.rr), c: RAR_CONF[d.rc || 0] || "Low" };
}


function rarityChip(d){
  const r = rarityOf(d);
  if(!r || RAR_BANDS.indexOf(r.b) < 3) return "";
  return `<span class="rarchip r${RAR_BANDS.indexOf(r.b)}" title="${esc(r.b)} — rarity ${r.s} of 100, confidence ${esc(r.c.toLowerCase())}. How scarce the release is, not what it is worth.">${r.s}</span>`;
}



var SCAR = null, _scarGot = null;
const SCAR_DEFAULT = { min_relevant: 30, min_owners: 5, emerging: 30, reliable: 200, strong: 1000 };



const SCAR_ANCHORS = [[0.0005,99],[0.002,95],[0.005,90],[0.01,85],[0.02,78],
                      [0.05,66],[0.10,55],[0.20,40],[0.40,22],[0.70,8],[1.0,0]];
function scarScore(rate){
  if(!(rate > 0)) return null;
  const A = SCAR_ANCHORS;
  if(rate <= A[0][0]) return A[0][1];
  if(rate >= A[A.length-1][0]) return A[A.length-1][1];
  for(let i=0;i<A.length-1;i++){
    const [r1,s1]=A[i], [r2,s2]=A[i+1];
    if(rate>=r1 && rate<=r2){
      const t=(Math.log10(rate)-Math.log10(r1))/(Math.log10(r2)-Math.log10(r1));
      return Math.round(s1 + t*(s2-s1));
    }
  }
  return A[A.length-1][1];
}
function scarQuality(n, cfg){
  if(n < cfg.min_relevant) return "Insufficient data";
  if(n < cfg.reliable)     return "Emerging";
  if(n < cfg.strong)       return "Reliable";
  return "Strong sample";
}


function scarLoad(){
  if(_scarGot) return _scarGot;
  if(typeof AUTH !== "object" || !AUTH || typeof AUTH.restJSON !== "function"){
    _scarGot = Promise.resolve(null); return _scarGot;
  }
  _scarGot = (async () => {
    try{
      

      const [rel, brands, cfg] = await Promise.all([
        AUTH.restJSON("/release_ownership_public?select=car_number,unique_owners,wishlist_count,onway_owners,some_owners_withheld"),
        AUTH.restJSON("/brand_collectors_public?select=brand,relevant_collectors,below_threshold"),
        AUTH.restJSON("/scarcity_config?select=*&id=eq.1")
      ]);
      const R = {}; (rel||[]).forEach(r => { R[r.car_number] = r; });
      const B = {}; (brands||[]).forEach(b => { B[b.brand] = b.relevant_collectors || 0; });
      const c = (cfg && cfg[0]) || {};
      SCAR = { rel: R, brands: B, cfg: {
        min_relevant: c.min_relevant_collectors != null ? c.min_relevant_collectors : SCAR_DEFAULT.min_relevant,
        min_owners:   c.min_owners_to_disclose != null ? c.min_owners_to_disclose : SCAR_DEFAULT.min_owners,
        emerging: c.emerging_at || SCAR_DEFAULT.emerging,
        reliable: c.reliable_at || SCAR_DEFAULT.reliable,
        strong:   c.strong_at   || SCAR_DEFAULT.strong },
        at: c.computed_at || null };
      return SCAR;
    }catch(e){
      

      SCAR = null; _scarGot = null; return null;
    }
  })();
  return _scarGot;
}


function aggReset(){
  SCAR = null; _scarGot = null;
  MKT = null; _mktGot = null;
}
function aggLoad(){
  if(typeof scarLoad !== "function") return Promise.resolve();
  return Promise.all([scarLoad(), mktLoad()]).then(() => {
    if(typeof OPEN_AT !== "undefined" && OPEN_AT > -1 && typeof openCard === "function") openCard(OPEN_AT);
    if(typeof render === "function") render();
  }).catch(() => {});
}


function scarcityOf(d){
  if(!SCAR || !d) return null;
  const cfg = SCAR.cfg;
  const bs = brandsOf(d);
  let relevant = 0, from = null;
  bs.forEach(b => { const n = SCAR.brands[b] || 0; if(n > relevant){ relevant = n; from = b; } });
  if(relevant < cfg.min_relevant)
    return { state:"insufficient", relevant, brand: from || bs[0],
             quality: scarQuality(relevant, cfg) };
  const row = SCAR.rel[d.n];
  

  const withheld = !!(row && row.some_owners_withheld);
  if(withheld)
    return { state: "withheld", relevant, brand: from,
             quality: scarQuality(relevant, cfg) };
  const owners = row ? (row.unique_owners || 0) : 0;
  const rate = owners / relevant;
  return { state: "ok", owners, relevant, brand: from, rate,
           pct: rate * 100, score: owners ? scarScore(rate) : 100,
           disclose: true,
           wishlist: row ? (row.wishlist_count || 0) : 0,
           quality: scarQuality(relevant, cfg) };
}

 
var MKT = null, _mktGot = null;
function mktLoad(){
  if(_mktGot) return _mktGot;
  if(typeof AUTH !== "object" || !AUTH || typeof AUTH.restJSON !== "function"){
    _mktGot = Promise.resolve(null); return _mktGot;
  }
  _mktGot = (async () => {
    try{
      const rows = await AUTH.restJSON("/market_metrics?select=*");
      const M = {}; (rows||[]).forEach(r => { M[r.car_number] = r; });
      MKT = M; return M;
    }catch(e){ MKT = null; _mktGot = null; return null; }    
  })();
  return _mktGot;
}
function marketOf(d){ return (MKT && d && MKT[d.n]) || null; }
const DEMAND_WORD = { low:"Low", moderate:"Moderate", high:"High", very_high:"Very high" };





function colourNote(d){
  if(!d || !d.col) return "";
  const name = (d.noname || !d.t) ? "" : String(d.t).trim();
  const c = String(d.col).trim();
  if(!c) return "";
  return name.toLowerCase().indexOf(c.toLowerCase()) < 0 ? c : "";
}
function photoAlt(d){
  if(!d) return "";
  const name = (d.noname || !d.t) ? "" : String(d.t).trim();
  const bits = [name || ("Release " + d.n)];
  const c = colourNote(d);
  if(c) bits.push(c);
  return bits.join(", ");
}


function packNum(d){
  if(!d || !d.pnum) return "";
  const p = String(d.pnum).trim();
  if(!p || p === String(d.n).trim()) return "";
  return `<span class="packnum" title="${esc(d.br === "Mainline" || (d.bs||[]).includes("Hot Wheels")
    ? "the collector number printed on the card. Hot Wheels re-uses these every year, so it names this car within its year rather than identifying it on its own"
    : "the number printed on the packaging. It is re-used, so it names this release within its run rather than identifying it on its own")}">no.${esc(p)}</span>`;
}
function card(d,idx){
  const cls=d.xc?"canc":d.o===1?"own":d.o===2?"ord":"miss";
  const _s=imgSrc(d);
  

  

  const img=_s?`<img loading="lazy" decoding="async" referrerpolicy="no-referrer" src="${_s}" data-remote="${remoteSrc(d)}" alt="${esc(photoAlt(d))}">`
              :detailKnown(d)?`<div class="noimg">no photo on file</div>`
              :`<div class="noimg pending" aria-hidden="true"></div>`;
  const pills=[];
  if(d.o===1){
    const t=tallies(d), multi=t.n>1;
    for(const [k,v] of Object.entries(t.cond))
      pills.push(`<span class="pill p-own">${k==="UNRECORDED"?"owned":k}${multi?` (${v})`:""}</span>`);
    for(const [k,v] of Object.entries(t.tag))
      pills.push(`<span class="pill p-chase">${k}${multi?` (${v})`:""}</span>`);
  }
  else if(d.o===2){
    pills.push(`<span class="pill p-ord">${d.ord?"ordered \u00b7 on the way":"on the way"}</span>`);
    

    if(d.w) pills.push(`<span class="pill p-want" title="this was on your want list and you have now ordered it">${["","want","priority","grail"][d.w]} \u2713</span>`);
  }
  else if(d.xc) pills.push(`<span class="pill p-canc">cancelled</span>`);
  else if(d.w){
    

    

    const _sh = d.sh || [];
    const _low = _sh.length ? Math.min(..._sh.map(z=>z[1])) : null;
    const _hit = d.mx!=null && _low!=null && _low<=d.mx;
    pills.push(`<span class="pill p-want">${["","want","priority","grail"][d.w]}${d.mx?` ≤ ${priv(d.mx)}`:""}</span>`);
    

    if(_hit) pills.push(`<span class="pill p-buy">under your ceiling at ${gbp(_low)}</span>`);
    else if(_low!=null) pills.push(`<span class="pill p-buy">buy ${gbp(_low)}</span>`);
  }
  else if(d.sh && d.sh.length) pills.push(`<span class="pill p-buy">buy ${gbp(Math.min(...d.sh.map(z=>z[1])))}</span>`);

  const money = d.o
    

    ? `<div class="money"><span class="v">${valOf(d) ? priv(valOf(d)) : "<span class='est'>not valued</span>"}${d.e&&valOf(d)&&!moneyIsPrivate()?"<span class='est'> est</span>":""}${qtyOf(d)>1&&valOf(d)&&!moneyIsPrivate()?`<span class='est'> (${priv(valOf(d)/qtyOf(d))} each)</span>`:""}</span>${paidOf(d)?`<span class="p">paid ${priv(paidOf(d))}${paidGaps(d)&&!moneyIsPrivate()?`<span class='est'> +${paidGaps(d)} unpriced</span>`:""}</span>`:`<span class="p">paid —</span>`}</div>`
    : "";
  const q_=qtyOf(d);
  

  if(d.ex) pills.push(`<span class="pill p-exc" title="${esc(d.ex.w)}">${esc(d.ex.c==="?"?"market not recorded":d.ex.c)}</span>`);
  

  if(Array.isArray(d.hwc)){
    const WORD={preowned:"pre-owned", loose:"loose", damaged:"damaged box"};
    const TIP ={preowned:"the shop listed this one as second hand",
                loose:"the shop listed this one out of its packaging",
                damaged:"the shop listed this one with a damaged box"};
    d.hwc.forEach(k=>{ if(WORD[k]) pills.push(
      `<span class="pill p-used" title="${TIP[k]}">${WORD[k]}</span>`); });
  }
  

  

  

  for(const _c of attrsOf(d)){
    const _a = attrDef(_c) || {};
    const _why = attrWhy(d, _c);
    pills.push(`<span class="pill p-tax tx-${esc(_c)}" title="${esc((_a.note||"") + (_why?" Established because "+_why+".":""))}">${esc(_a.short||_c)}</span>`);
  }
  

  {
    const _c = colourNote(d);
    if(_c) pills.push(`<span class="pill p-col" title="the colour recorded for this release, which its name does not state">${esc(_c)}</span>`);
    

    else if(d.tnote) pills.push(`<span class="pill p-note" title="${esc(d.tnote)}">colour not stated</span>`);
    

    else if(d.snote) pills.push(`<span class="pill p-note" title="${esc(d.snote)}">name not unique</span>`);
    

    if(d.tvar) pills.push(`<span class="pill p-col" title="how Tomytec's own product name distinguishes this release from the one before it">${esc(d.tvar)}</span>`);
  }
  if(d.fam)
    pills.push(`<span class="pill p-series" title="the family this one belongs to inside its range">${esc(d.fam)}${d.hwpos?" "+esc(d.hwpos):""}</span>`);
  if(d.hwbox){
    const WORD={case:"sealed case", pack:"multi-pack", set:"series set"};
    pills.push(`<span class="pill p-box" title="a box of cars rather than a car, so it counts as nothing on its own">${WORD[d.hwbox]||"box"}</span>`);
  }
  

  if(d.bond) pills.push(`<span class="pill p-bond" title="${brandsOf(d).includes("Mini GT")?"part of the Mini GT 007 line":"a car from the James Bond films"}">007</span>`);
  

  if(d.br && line==="__all" && (brand==="__all" || d.br !== brand))
    pills.push(`<span class="pill p-series">${esc(d.br)}</span>`);
  

  if(brandsOf(d).length>1)
    pills.push(`<span class="pill p-collab" title="one release, sold in ${brandsOf(d).length} catalogues, counted once overall">${brandsOf(d).join(" × ")}</span>`);
  else if(d.cb)
    pills.push(`<span class="pill p-collab" title="collaboration">${esc(d.cb)}</span>`);
  

  if(d.eta && !d.s){
    const late=etaLate(d.eta);
    pills.push(`<span class="pill p-eta${late?" p-late":""}" title="${late?"this estimate has already passed, so the car is running late":"estimated release, as quoted by the shops taking pre-orders"}">${esc(d.eta)}${late?" late":""}</span>`);
  }
  

  if(d.hand && /^(LHD|RHD|LHD\/RHD)$/i.test(String(d.hand).trim()))
    pills.push(`<span class="pill p-series" title="which side the steering wheel is on">${esc(d.hand.trim().toUpperCase())}</span>`);
  

  const ovl=[];
  if(q_>1) ovl.push(`<span class="pill p-set" title="you hold ${q_} copies">×${q_}</span>`);
  if(d.k){
    const sp=setProgress(d);
    if(sp) ovl.push(`<span class="pill p-set" title="how many of this set you have">set ${sp.have}/${sp.n}${sp.coming?` +${sp.coming}`:""}</span>`);
    else ovl.push(`<span class="pill p-set">set</span>`);
  }
  if(!d.s && !d.eta) ovl.push(`<span class="pill p-pre">pre-order</span>`);
  

  if(d.yr) ovl.push(`<span class="pill p-pre">${d.yr}</span>`);
  

  ovl.push(scalePill(d));
  

  if(d.cyr) ovl.push(`<span class="pill p-note" title="The year of the car itself, as the maker names it. Not the year this model was sold.">car ${d.cyr}</span>`);
  if(d.fs) ovl.push(`<span class="pill p-pre" title="not a release date: the month a UK shop first listed it">~${String(d.fs).slice(0,4)}</span>`);
  const foot=[...ovl,...pills];

  const bc=brandColour(d);
  const marque=esc(d.m||brandsOf(d)[0]||"");
  const wantOn=d.w?" on":"", ownOn=d.o===1?" on":"";
  return `<article class="c ${cls}${editMode?" editing":""}" data-i="${idx}" data-n="${esc(d.n)}" style="--bc:${bc}" tabindex="0" role="button" aria-label="${d.noname ? (d.jp ? esc(d.jp) : "name not recorded") : esc(d.t)}, ${esc(d.n)}">
    <div class="ph">${rarityChip(d)}${d.chase?`<span class="chasedot" title="a chase version of this model was made \u2014 this mark is not a claim that you have one, and it is not a claim that this row IS the chase">\u25c6</span>`:""}${img}</div>${d.o?`<div class="tick" title="${d.o===2?"on the way":"in your collection"}">✓</div>`:""}
    <div class="meta">
      <div class="marque">${marque}</div>
      <div class="t">${d.noname
        /* A NAME IN JAPANESE IS STILL A NAME.
           390 rows carried Kyosho's or Tomytec's own name for the release and showed "name not
           recorded, nobody has named it" over the top of it, because the English name is what
           this looked at. The maker HAS named them; it named them in Japanese, which is what a
           collector looking for one of those releases will type. So the maker's own name is
           shown, marked as the maker's rather than as a translation, and "not recorded" is
           kept for the rows where nothing anywhere has a name. */
        ? (d.jp
           ? `${hl(d.jp)} <span class="est">\u2014 the maker's own name; no English one is recorded</span>`
           : `<span class="est">name not recorded \u2014 ${esc(d.nonamewhy || "no source on file names this one")}</span>`)
        : hl(d.t)}</div>
      <div class="numrow"><span class="num">${hl(d.n)}</span>${packNum(d)}
        <span class="act">
          <button type="button" class="a-own${ownOn}" data-act="own" aria-pressed="${d.o===1}" title="${d.o===1?"You have this one":"Mark as mine"}" aria-label="${d.o===1?"In your collection":"Add to your collection"}"><svg viewBox="0 0 24 24"><path d="M4 12.5l5.2 5.2L20 7"/></svg></button>
          <button type="button" class="a-want${wantOn}" data-act="want" aria-pressed="${!!d.w}" title="${d.w?"On your want list":"Add to your want list"}" aria-label="${d.w?"On your want list":"Add to your want list"}"><svg viewBox="0 0 24 24"><path d="M12 20s-7.5-4.6-7.5-9.4A4.1 4.1 0 0 1 12 8a4.1 4.1 0 0 1 7.5 2.6C19.5 15.4 12 20 12 20z"/></svg></button>
        </span>
      </div>
      <div class="foot">${foot.join("")}</div>${money}</div>${editBar(d)}<div class="edge"></div></article>`;
}

let current=[];


var _elsewhereTimer = 0;
function elsewhereNote(){
  const box=document.getElementById("elsewhere");
  if(!box) return;
  box.style.display="none"; box.innerHTML="";
  

  const scope = line!=="__all" ? line
              : (brand!=="__all" ? brand : "");
  if(!q || !scope) return;
  const here=current.length;
  const all=DATA.filter(d=>!heldBack(d) && matchesQ(d)).length;
  if(all<=here) return;
  const n=all-here;
  box.style.display="block";
  

  const word = n===1 ? "match" : "matches";
  box.innerHTML = `${n.toLocaleString()} ${here ? "more " : ""}${word} outside `
    + `<b>${esc(lineName(scope))}</b>. <button class="chip" id="seeall">Search every catalogue</button>`;
  document.getElementById("seeall").onclick=()=>{
    brand="__all"; line="__all";
    fillLines(); paintBrands(); fillMarques(); recount(); render();
  };
}
 






var _relIndex = null;
function relatedOf(n){
  if(_relIndex === null){
    _relIndex = {};
    const G = (typeof RELATED !== "undefined" && RELATED) ? RELATED : [];
    for(const g of G)
      for(const a of g.ns)
        for(const b of g.ns)
          if(a !== b) (_relIndex[a] = _relIndex[a] || []).push({n:b, r:g.r});
  }
  return _relIndex[n] || [];
}
 
const RELATED_SAYS = {
  drive:   ["The same release in the other drive",
            "Paragon numbers most PARA64 cars twice, left- and right-hand drive. Both are separate things to own."],
  shared: ["The same casting, from the other maker",
           "Pop Race and XCarToys share tooling, so a casting can be issued by each of them. These are separate releases of it and both are separate things to own. Matched on the name, because neither maker prints a number that carries the other's."],
  realcar: ["The same car, modelled by somebody else",
            "One car raced once, and more than one maker has made a model of it. These are separate releases of the same real machine: the same season, the same chassis, the same number on the nose."],
  hunt:    ["The same casting, in the ordinary run",
            "A Treasure Hunt is not a different car. It is this casting, run in a special finish and mixed into the same assortment at about one per seventy-two car case. Both are separate things to own. Matched on the casting and the year, and deliberately not on the collector number: modern hunts share the number with the mainline car and the 2000 to 2002 ones had a sequence of their own."],
  chase:   ["The chase, and the car it was short-packed against",
            "A premium set holds one short-packed car. These are the two releases of that casting in that set, and they are separate things to own. Matched on the casting, the year and the assortment."],
  casting: ["The same casting, issued again",
            "Tomytec numbers Limited Vintage by casting and then by variant, so these share their tooling and differ in colour or livery."]
};



function scaleOf(d){
  const kind = scaleKindOf(d);
  if(d.sc) return {s:String(d.sc), own:true, kind};
  const L = (typeof LINE_SCALE === "object" && LINE_SCALE) ? LINE_SCALE[d.br] : "";
  return L ? {s:L, own:false, kind} : {s:"", own:false, kind};
}


function scaleKindOf(d){
  if(!d) return "";
  const K = (typeof SCALE_KIND === "object" && SCALE_KIND) ? SCALE_KIND[d.br] : "";
  return K || "";
}
function scaleWhy(d, v){
  if(v.own){
    return v.kind === "box"
      ? (d.br || "this range") + " is built to fill a box rather than to a ratio, so this "
        + "is the scale this release works out at"
      : "the scale this release states";
  }
  return "every " + (d.br || "release in this range") + " is built to this scale";
}


function scaleWords(d){
  const v = scaleOf(d);
  if(v.s) return {text: v.s.replace("/", ":"), title: scaleWhy(d, v), known: true};
  if(v.kind === "box") return {text: "box scale", known: false,
    title: (d.br || "this range") + " is built to fill a box rather than to a ratio, and no "
         + "source states the ratio this release works out at"};
  return {text: "scale not stated", known: false,
    title: "no source states a scale for this one, so none is claimed"};
}
function scalePill(d){
  const w = scaleWords(d);
  return `<span class="pill p-scale${w.known ? "" : " p-scale-none"}" title="${esc(w.title)}">${esc(w.text)}</span>`;
}
function scaleChip(d){
  const w = scaleWords(d);
  return `<span class="scale${w.known ? "" : " noscale"}" title="${esc(w.title)}">${esc(w.text)}</span>`;
}


const EXALL = () => DATA.filter(d => isRelease(d) && inLine(d) && d.ex);
const BONDALL = () => DATA.filter(d => isRelease(d) && inLine(d) && d.bond);
function excGroups(){
  const m = new Map();
  for(const d of EXALL()){
    const c = d.ex.c;
    const g = m.get(c) || {c, n:0, have:0, coming:0};
    g.n++; if(d.o===1) g.have++; else if(d.o===2) g.coming++;
    m.set(c, g);
  }
   
  return [...m.values()].sort((a,b)=> (a.c==="?") - (b.c==="?") || b.n-a.n || a.c.localeCompare(b.c));
}
function excLabel(c){ return c==="?" ? "Market not recorded" : c; }
function drawExcBar(){
  const bar = $("#excbar");
  const groups = excGroups();
  const all = EXALL(), bond = BONDALL();
  const tally = rows => ({n:rows.length, have:rows.filter(d=>d.o===1).length,
                          coming:rows.filter(d=>d.o===2).length});
  const chip = (key, name, t, extra) =>
    `<button class="excg${extra||""}${excGroup===key?" on":""}" data-g="${esc(key)}">`
    + `<b>${esc(name)}</b><i>${t.have}/${t.n}${t.coming?" +"+t.coming:""}</i></button>`;
  if(!all.length && !bond.length){ bar.innerHTML=""; bar.style.display="none"; return; }
  

  let html = `<p class="exchead">By market and where it was sold</p>`;
  html += `<div class="excrow">` + chip("", "Every exclusive", tally(all))
        + groups.map(g => chip(g.c, excLabel(g.c), {n:g.n, have:g.have, coming:g.coming})).join("")
        + `</div>`;
  if(bond.length){
    html += `<p class="exchead">Licensed film line</p><div class="excrow">`
          + chip("007", "007 movie cars", tally(bond), " bond") + `</div>`;
  }
  

  const outside = DATA.filter(d => isRelease(d) && !inLine(d) && (d.ex || d.bond)).length;
  const scopedBy = line !== "__all" ? lineName(line) : (brand !== "__all" ? brand : "");
  if(outside && scopedBy){
    html += `<p class="excnote"><b>${outside}</b> more sit outside <b>${esc(scopedBy)}</b>. `
          + `<button class="chip" id="excall">Show every catalogue</button></p>`;
  }
  html += `<p class="excnote">A country here means the release was limited to that market or to an `
        + `event held there, not that the car wears its flag: a Macau GP livery sold worldwide is not `
        + `a Macau exclusive. Packaging variants are not counted either, so a car boxed for Toys R Us `
        + `or Mijo stays with the rest of the catalogue. The number on each chip is what you own out `
        + `of what exists, and +n is what is on the way.</p>`;
  bar.innerHTML = html;
  bar.style.display = "block";
  bar.onclick = e => {
    if(e.target.id === "excall"){
      line = "__all"; $("#line").value = "__all";
      brand = "__all";
      if(typeof clearCollections === "function") clearCollections();
      fillLines(); fillMarques(); if(typeof paintBrands === "function") paintBrands();
      recount(); render();
      return;
    }
    const b = e.target.closest(".excg"); if(!b) return;
    excGroup = b.dataset.g; render(); window.scrollTo({top:0, behavior:"smooth"});
  };
}



var EXTRA_VIEWS = (typeof EXTRA_VIEWS === "object" && EXTRA_VIEWS) ? EXTRA_VIEWS : {};
function render(){
  $("#stats").style.display = view==="stats"?"grid":"none";
  $("#value").style.display = view==="value"?"block":"none";
   
  { const bx=document.getElementById("badges"); if(bx) bx.style.display = view==="badge"?"block":"none"; }
  { const px=document.getElementById("profile"); if(px) px.style.display = view==="me"?"block":"none"; }
  const extra = EXTRA_VIEWS[view] || null;
  for(const k in EXTRA_VIEWS){
    const el = document.getElementById(EXTRA_VIEWS[k].id);
    if(el) el.style.display = (k===view) ? "block" : "none";
  }
  

  $("#grid").style.display  = (view==="stats"||view==="value"||view==="badge"||view==="me"||extra)?"none":"";
  $("#excbar").style.display = view==="exc"?"block":"none";
  

  const chartish = view==="stats"||view==="value"||view==="badge"||view==="me"||!!extra;
  const ctl=document.querySelector(".tb-ctl"); if(ctl) ctl.hidden=chartish;
  const af=document.getElementById("activef"); if(af) af.hidden=chartish;
  

  const ownScreen = view==="badge" || view==="me" || !!extra;
  for(const id of ["brands","lines","kpis"]){
    const el = document.getElementById(id);
    if(!el) continue;
    if(ownScreen){ el.dataset.hidFor = "1"; el.style.display = "none"; }
    else if(el.dataset.hidFor){ delete el.dataset.hidFor; el.style.display = ""; }
  }
  const heroEl = document.querySelector(".hero");
  if(heroEl) heroEl.classList.toggle("bare", ownScreen);
  if(view!=="exc" && excGroup) excGroup="";     
  

  current=subset();
  if(view==="stats"){ $("#empty").style.display="none"; $("#count").textContent=""; return drawStats(); }
  if(view==="value"){ $("#empty").style.display="none"; $("#count").textContent=""; return drawValue(); }
  if(view==="me"){ $("#empty").style.display="none"; $("#count").textContent="";
    if(typeof drawProfile==="function") drawProfile();
    if(typeof paintHero==="function") paintHero();
    if(typeof destKpis==="function"){ const h=destKpis(); $("#kpis").innerHTML = h || ""; }
    return; }
  if(extra){ $("#empty").style.display="none"; $("#count").textContent="";
    if(typeof extra.draw==="function"){ try{ extra.draw(); }catch(e){ console.error(e); } }
    if(typeof paintHero==="function") paintHero();
    if(typeof destKpis==="function"){ const h=destKpis(); $("#kpis").innerHTML = h || ""; }
    return; }
  if(view==="badge"){ $("#empty").style.display="none"; $("#count").textContent="";
    if(typeof drawBadges==="function") drawBadges();
    if(typeof paintHero==="function") paintHero();
    if(typeof destKpis==="function"){ const h=destKpis(); $("#kpis").innerHTML = h || KPI_DEFAULT || ""; }
    return; }
  if(view==="exc") drawExcBar();
  

  if(view==="dupe"){
    $("#count").textContent = current.length
      ? current.length.toLocaleString()+(current.length===1?" car":" cars")+" you hold more than once, "+dupeCopies+" spare "+(dupeCopies===1?"copy":"copies")
      : "no duplicates";
  } else if(view==="exc"){
    const have=current.filter(d=>d.o===1).length, coming=current.filter(d=>d.o===2).length;
    const what = excGroup==="007" ? "007 cars" : excGroup ? excLabel(excGroup)+" exclusives" : "exclusives";
    $("#count").textContent = current.length
      ? have+" of "+current.length+" "+what+(coming?", "+coming+" on the way":"")
      : "none";
  } else {
    

    

    

    (function(){
      let boxes = 0;
      for(const d of current) if(d.k) boxes++;
      const el = $("#count");
      

      const _seen = (typeof queryPlan === "function" && q) ? (queryPlan().seenFor || "") : "";
      el.textContent = current.length.toLocaleString() + " shown"
        + (_seen ? " \u00b7 " + esc(q.trim()) + " is filed here as " + esc(_seen) : "")
        + (boxes ? " \u00b7 " + boxes + (boxes === 1 ? " set box, counted as nothing"
                                                      : " set boxes, counted as nothing") : "");
      if(boxes) el.title = current.length.toLocaleString() + " cards on screen, "
        + boxes + " of which " + (boxes===1?"is a set box that counts":"are set boxes that count")
        + " as nothing on " + (boxes===1?"its":"their") + " own. The cars inside "
        + (boxes===1?"it":"them") + " each count as one.";
      else el.removeAttribute("title");
    })();
  }
  $("#empty").style.display=current.length?"none":"block";
  if(!current.length) $("#empty").innerHTML=emptyState();
  

  

  if(_elsewhereTimer) cancelAnimationFrame(_elsewhereTimer);
  _elsewhereTimer = requestAnimationFrame(() => { _elsewhereTimer = 0; elsewhereNote(); });
  if(typeof paintViewMode==="function") paintViewMode();
  if(typeof paintFilters==="function") paintFilters();
  if(typeof paintLines==="function") paintLines();
  if(typeof paintHero==="function") paintHero();
   
  if(typeof destKpis==="function"){
    const h=destKpis();
    if(h) $("#kpis").innerHTML=h;
    else if(KPI_DEFAULT) $("#kpis").innerHTML=KPI_DEFAULT;
  }
  paintGrid(true);
}



function pageStep(){
  

  try{ return window.matchMedia("(max-width:760px)").matches ? 90 : 600; }
  catch(e){ return 600; }
}
let shownN = 0;


const FIRST_PAINT = 120;


let _paintGen = 0;
function paintGrid(reset){
  const step = pageStep(), g = $("#grid");
  const gen = ++_paintGen;
  if(reset){
    shownN = Math.min(current.length, step);
    const first = Math.min(shownN, FIRST_PAINT);
    

    if(typeof needDetail === "function") needDetail(current.slice(0, shownN));
    

    g.innerHTML = current.slice(0, first).map((d, k) => card(d, k)).join("");
    if(first < shownN){
      

      const rest = () => {
        if(gen !== _paintGen) return;          
        const w = document.getElementById("morewrap"); if(w) w.remove();
        g.insertAdjacentHTML("beforeend",
          current.slice(first, shownN).map((d, k) => card(d, first + k)).join(""));
        if(typeof queuePhotos === "function") queuePhotos();
        moreButton(step);
      };
      if(typeof requestIdleCallback === "function") requestIdleCallback(rest, {timeout:400});
      else requestAnimationFrame(rest);
    }
  }else{
    

    const from = shownN;
    shownN = Math.min(current.length, shownN + step);
     
    if(typeof needDetail === "function") needDetail(current.slice(from, shownN));
    const w = document.getElementById("morewrap"); if(w) w.remove();
    g.insertAdjacentHTML("beforeend",
      current.slice(from, shownN).map((d, k) => card(d, from + k)).join(""));
  }
   
  if(shownN > 0 && typeof queuePhotos === "function") queuePhotos();
  moreButton(step);
}


function moreButton(step){
  const g = $("#grid");
  const old = document.getElementById("morewrap"); if(old) old.remove();
  const left = current.length - shownN;
  if(left <= 0) return;
  const next = Math.min(left, step || pageStep());
  g.insertAdjacentHTML("beforeend",
    `<div id="morewrap" style="grid-column:1/-1;text-align:center;padding:18px">` +
    `<button class="chip" id="more">Show ${next} more` +
    `<span style="opacity:.6;margin-left:8px">${left} still to come</span></button></div>`);
  $("#more").onclick = () => paintGrid(false);
}

 
function drawValue(){
  

  const POOLALL = DATA.filter(d => isRelease(d) && inLine(d));
  const shelf   = POOLALL.filter(isOwned);
  const coming  = POOLALL.filter(isIncoming);

  

  const shelfValue = shelf.reduce((s,d)=>s+valOf(d),0);
  const comingValue = coming.reduce((s,d)=>s+valOf(d),0);
  const spent   = shelf.reduce((s,d)=>s+paidReceipt(d),0);
  const standIn = shelf.reduce((s,d)=>s+paidRetail(d),0);
  const spentComing = coming.reduce((s,d)=>s+paidReceipt(d),0);
  const withReceipt = shelf.filter(d=>paidReceipt(d)>0);
  const withRetail  = shelf.filter(d=>paidRetail(d)>0);
  const noPrice     = shelf.filter(d=>!paidOf(d));
  

  const receiptValue = withReceipt.reduce((s,d)=>s+valOf(d),0);
  const diff = receiptValue - spent, pc = spent ? diff/spent*100 : 0;
  const est = shelf.filter(d=>d.e).length;
  

  const unsourced = shelf.filter(d => d.vu && (d.v || 0));
  const cards=[
    ["","Collection value",priv(shelfValue),
      `${shelf.length} release${shelf.length===1?"":"s"} on the shelf, ${piecesIn(shelf)} piece${piecesIn(shelf)===1?"":"s"}. ${shelf.length-est} priced from live UK stock, ${est} estimated${unsourced.length?`, and ${unsourced.length} carry a figure with no source on file`:""}. Anything still on its way is not counted here.`],
    ...(coming.length?[["ord","On the way",priv(comingValue),
      `${coming.length} paid for and not arrived${spentComing?`, ${priv(spentComing)} spent on them`:""}. Not part of the collection until they land.`]]:[]),
    ["","Total paid",priv(spent),
      `What you actually spent, from ${withReceipt.length} receipt${withReceipt.length===1?"":"s"}. ${noPrice.length} car${noPrice.length===1?" has":"s have"} no price on file${withRetail.length?` and ${withRetail.length} carry a retail price instead, which is not counted here`:""}.`],
    ...(withRetail.length?[["","Filled in at retail",priv(standIn),
      `${withRetail.length} car${withRetail.length===1?"":"s"} with no receipt anywhere, priced at what they sold for new. An estimate, kept out of Total paid.`]]:[]),
    [moneyIsPrivate()?"":(diff>=0?"up":"dn"),"Change on those "+withReceipt.length,
      privAmt((diff>=0?"+":"−")+money(Math.abs(diff))),
      `Worth ${priv(receiptValue)} against ${priv(spent)} paid, ${privAmt((pc>=0?"+":"−")+Math.abs(pc).toFixed(1)+"%")}. Only the cars with a receipt, because they are the only ones where both halves are real.`],
    ["","Average paid", withReceipt.length?priv(spent/withReceipt.length):"—",
        withReceipt.length?`Across the ${withReceipt.length} cars with a receipt. Dearest single purchase ${priv(Math.max(...withReceipt.map(d=>paidReceipt(d))))}.`
                   :"No receipts recorded for this catalogue yet."]
  ].map(([k,l,v,s])=>`<div class="vc ${k}"><b>${v}</b><i>${l}</i><small>${s}</small></div>`).join("");

  

  const POOL=POOLALL;
  const byM={};
  for(const d of POOL){
    const m=byM[d.m]||(byM[d.m]={n:d.m,tot:0,own:0,val:0,paid:0});
    m.tot++; if(isOwned(d)){m.own++; m.val+=valOf(d); m.paid+=paidReceipt(d);}
  }
  const brands=Object.values(byM).filter(m=>m.own>0).sort((a,b)=>b.val-a.val);
  for(const m of brands){
    const withP=POOL.filter(d=>d.m===m.n&&isOwned(d)&&paidReceipt(d)>0);
    m.paidVal=withP.reduce((s,d)=>s+valOf(d),0);
    m.paidSum=withP.reduce((s,d)=>s+paidReceipt(d),0);
  }
  const brandRows=brands.map(m=>{
    const g=m.paidVal-m.paidSum;
    const gc=m.paidSum? (moneyIsPrivate() ? MONEY_MASK
      : `<span style="color:${g>=0?'var(--own)':'#f87171'}">${g>=0?"+":"−"}${money(Math.abs(g))}</span>`) : "—";
    return `<tr data-m="${m.n}"><td>${m.n}</td><td class="r">${m.own}/${m.tot}</td>`+
      `<td style="width:110px"><span class="minibar"><i style="width:${(m.own/m.tot*100).toFixed(1)}%"></i></span></td>`+
      `<td class="r">${priv(m.val)}</td><td class="r">${m.paidSum?priv(m.paidSum):"—"}</td>`+
      `<td class="r">${gc}</td><td class="r">${priv(m.val/m.own)}</td></tr>`;
  }).join("");

  const top=[...shelf].sort((a,b)=>(b.v||0)-(a.v||0)).slice(0,12).map(d=>`<tr>
    <td class="r" style="color:var(--tx3)">${esc(d.n)}</td><td>${esc(d.t)}</td>
    <td class="r">${priv(d.v)}${d.e?" <span class='est'>est</span>":""}</td>
    <td class="r">${paidReceipt(d)?priv(paidReceipt(d)):(paidRetail(d)?priv(paidRetail(d))+" <span class='est'>retail</span>":"—")}</td></tr>`).join("");

  

  const movers=withReceipt.map(d=>({...d,g:valOf(d)-paidReceipt(d),_paid:paidReceipt(d)})).sort((a,b)=>b.g-a.g);
  const mk=list=>list.map(d=>`<tr><td class="r" style="color:var(--tx3)">${esc(d.n)}</td><td>${esc(d.t)}</td>
    <td class="r">${priv(d._paid)}</td><td class="r">${priv(valOf(d))}</td>
    <td class="r"${moneyIsPrivate()?"":` style="color:${d.g>=0?'var(--own)':'#f87171'}"`}>${moneyIsPrivate()?MONEY_MASK:((d.g>=0?"+":"−")+money(Math.abs(d.g)))}</td></tr>`).join("");

  

  const byCat={};
  for(const d of POOL){
    if(!isOwned(d)) continue;
    for(const b of brandsOf(d)){
      const c=byCat[b]||(byCat[b]={n:b,own:0,val:0,paid:0,priced:0});
      c.own++; c.val+=valOf(d); c.paid+=paidReceipt(d); if(paidReceipt(d)>0) c.priced++;
    }
  }
  const catRows=Object.values(byCat).sort((a,b)=>b.paid-a.paid).map(c=>
    `<tr><td><span class="cdot" style="background:${brandColourName(c.n)}"></span>${esc(c.n)}</td>
     <td class="r">${c.own}</td><td class="r">${c.paid?priv(c.paid):"—"}</td>
     <td class="r">${priv(c.val)}</td>
     <td class="r">${c.own?Math.round(c.priced/c.own*100):0}%</td></tr>`).join("");
  const dearest=[...withReceipt].sort((a,b)=>paidReceipt(b)-paidReceipt(a)).slice(0,10).map(d=>`<tr>
    <td class="r" style="color:var(--tx3)">${esc(d.n)}</td><td>${esc(d.t)}</td>
    <td class="r">${priv(paidReceipt(d))}</td><td class="r">${d.src&&d.src!=="RRP"?esc(d.src):"—"}</td></tr>`).join("");
  const unpriced=noPrice;
  const unpricedRows=unpriced.slice(0,60).map(d=>`<tr class="upr" data-n="${esc(d.n)}">
    <td class="r" style="color:var(--tx3)">${esc(d.n)}</td><td>${esc(d.t)}</td>
    <td class="r"><span class="est">no price</span></td></tr>`).join("");

  $("#value").innerHTML=`${moneyIsPrivate()?`<p class="vnote privnote">Financial values are hidden. Everything on this page is still being worked out from your real figures — only the display is covered. <button type="button" class="linkish" id="valshow">Show them</button></p>`:""}<div class="vcards">${cards}</div>
    <p class="vnote">Paid is what you actually spent, from your own receipts. A car with no receipt
      anywhere carries a retail price instead; that is an estimate, it is shown on its own and it is
      never added into Paid. Value is also an estimate, usually the cheapest price a tracked UK shop
      is asking today, and it is never treated as a sale price. Everything here counts what is on the
      shelf; anything still on its way has its own figure and is not part of the collection until it
      arrives.</p>
    <div class="stats" style="padding:0">
      <div class="panel"><h3>By catalogue</h3>
        <p class="sub">A car in two catalogues is counted once overall but appears under both here, which is why these rows add up to more than the collection.</p>
        <table class="t"><thead><tr><th>Catalogue</th><th class="r">Cars</th><th class="r">Paid</th><th class="r">Value</th><th class="r">Priced</th></tr></thead>
        <tbody>${catRows||'<tr><td colspan="5" class="est">Nothing owned in this scope yet.</td></tr>'}</tbody></table></div>
      <div class="panel"><h3>Dearest purchases</h3>
        <p class="sub">By what you actually paid, not by what it is worth now. Retail stand-ins are left out.</p>
        <table class="t"><thead><tr><th class="r">No.</th><th>Model</th><th class="r">Paid</th><th class="r">From</th></tr></thead>
        <tbody>${dearest||'<tr><td colspan="4" class="est">No purchase prices recorded yet.</td></tr>'}</tbody></table></div>
      <div class="panel"><h3>Missing a price <b class="cnt">${unpriced.length}</b></h3>
        <p class="sub">Cars on your shelf with no price on file at all. Tap one to fill it in.${withRetail.length?` A further ${withRetail.length} carry a retail price rather than a receipt.`:""}${unpriced.length>60?" First sixty shown.":""}</p>
        <table class="t"><tbody>${unpricedRows||'<tr><td class="est">Every car you own has a price recorded.</td></tr>'}</tbody></table></div>
      <div class="panel panelwide"><h3>By marque</h3>
        <p class="sub">Quantity and value of what you own, biggest holding first. Paid and Gain cover only the cars with a receipt.</p>
        <table class="t"><thead><tr><th>Marque</th><th class="r">Owned</th><th></th><th class="r">Value</th><th class="r">Paid</th><th class="r">Gain</th><th class="r">Avg</th></tr></thead>
        <tbody>${brandRows}</tbody></table></div>
      <div class="panel"><h3>Most valuable</h3><p class="sub">Top twelve cars you own.</p>
        <table class="t"><thead><tr><th class="r">No.</th><th>Model</th><th class="r">Value</th><th class="r">Paid</th></tr></thead><tbody>${top}</tbody></table></div>
      <div class="panel"><h3>Best buys</h3><p class="sub">Biggest gain over what you paid.</p>
        <table class="t"><thead><tr><th class="r">No.</th><th>Model</th><th class="r">Paid</th><th class="r">Value</th><th class="r">Gain</th></tr></thead><tbody>${mk(movers.slice(0,10))}</tbody></table></div>
      <div class="panel"><h3>Paid over the odds</h3><p class="sub">Where value sits below what you paid. Sealed and out-of-production cars often read low here because the estimate follows current retail.</p>
        <table class="t"><thead><tr><th class="r">No.</th><th>Model</th><th class="r">Paid</th><th class="r">Value</th><th class="r">Gain</th></tr></thead><tbody>${mk(movers.slice(-10).reverse())}</tbody></table></div>
    </div>`;
}

 
function bars(title,sub,items){
  return `<div class="panel"><h3>${title}</h3><p class="sub">${sub}</p>`+items.map(([lab,o,t])=>{
    const pc=t?o/t*100:0;
    return `<div class="row"><span class="lab">${lab}</span><span class="track"><i style="width:${pc.toFixed(1)}%"></i></span><span class="val">${o}/${t}</span></div>`;
  }).join("")+`</div>`;
}
function drawStats(){
  
  
  

  const P = DATA.filter(d => isRelease(d) && inLine(d));
  const myP = P.filter(isOwned);
  const comingP = P.filter(isIncoming);
  const lineLabel = line!=="__all" ? line
                  : brand==="__all" ? "your whole collection"
                  : "all of " + brand;
  

  const numbered = line!=="__all" ? P.filter(d=>d.b>0) : [];
  const bands=[];
  if(numbered.length){
    const top = Math.max(...numbered.map(d=>d.b));
    const step = top>600 ? 100 : top>200 ? 50 : 25;
    for(let s=0;s<=top;s+=step){
      const a=numbered.filter(d=>d.b>=s&&d.b<s+step);
      if(a.length) bands.push([`${s||1}–${s+step-1}`,a.filter(isOwned).length,a.length]);
    }
  }
  

  const _mk = new Map();
  for(const d of P){
    let e = _mk.get(d.m); if(!e) _mk.set(d.m, e = [d.m, 0, 0]);
    e[2]++; if(isOwned(d)) e[1]++;
  }
  const mk=[..._mk.values()].sort((x,y)=>(y[1]-x[1])||(y[2]-x[2])).slice(0,20);
  

  

  const _sc = new Map();
  for(const d of P){
    const v = scaleOf(d).s;
    const k = v || (scaleKindOf(d) === "box" ? "__box" : "__none");
    let e = _sc.get(k); if(!e) _sc.set(k, e = [k, 0, 0]);
    e[2]++; if(isOwned(d)) e[1]++;
  }
  const _den = v => { const m = String(v).match(/(\d+)\s*$/); return m ? +m[1] : 1e9; };
  const scales = [..._sc.values()]
    .filter(e => e[1] > 0)
    .sort((a, b) => _den(a[0]) - _den(b[0]) || String(a[0]).localeCompare(String(b[0])))
    .map(e => [e[0] === "__box" ? "box scale"
             : e[0] === "__none" ? "scale not stated"
             : String(e[0]).replace("/", ":"), e[1], e[2]]);
   
  const scaleWorth = scales.length > 1;

  const GRADES = ["SEALED","MINT","GOOD","FAIR"];
  const graded = myP.filter(d => GRADES.indexOf(d.c) > -1).length;
  const cond = GRADES.map(c=>[c,myP.filter(d=>d.c===c).length,myP.length])
    .filter(r=>r[1]>0);
  if(myP.length - graded > 0) cond.push(["Not recorded", myP.length - graded, myP.length]);
  

  let _relN = 0, _relOwn = 0, _preN = 0, _preOwn = 0;
  for(const d of P){
    const got = isOwned(d);
    if(d.s){ _relN++; if(got) _relOwn++; }
    else   { _preN++; if(got) _preOwn++; }
  }
  const rel=[["Released",_relOwn,_relN],["Pre-order",_preOwn,_preN]].filter(r=>r[2]>0);
  const owners=[["Owned",myP.length,P.length]];
  if(comingP.length) owners.push(["On the way",comingP.length,P.length]);
  

  

  const _cat = new Map();
  let _sharedN = 0, _uniqueN = 0;
  for(const d of DATA){
    if(!isRelease(d)) continue;
    _uniqueN++;
    const bs = brandsOf(d), got = isOwned(d);
    if(bs.length > 1) _sharedN++;
    for(const bn of bs){
      let e = _cat.get(bn); if(!e) _cat.set(bn, e = [bn, 0, 0]);
      e[2]++; if(got) e[1]++;
    }
  }
  

  const cats = BRANDS.map(b => _cat.get(b)).filter(r => r && r[2] > 0);
  const shared = { length: _sharedN };
  const uniqueAll = { length: _uniqueN };
  $("#stats").innerHTML=
    

    `<p class="sub" style="margin:0 0 14px">Except where a panel says otherwise, every figure below counts <b style="font-weight:600">${esc(lineLabel)}</b> only. Owned means on the shelf; anything still on its way is counted separately. Use the catalogue buttons and the line dropdown above to change what is counted.</p>`+
    (cats.length>1?bars("Across every catalogue \u2014 not just this one",
      `Owned against the size of each catalogue. ${uniqueAll.length.toLocaleString()} cars in total`
      + (shared.length?`, of which ${shared.length} belong to two catalogues and are counted once in that total and once in each catalogue below. The bars therefore add up to more than the collection does.`:"."),
      cats):"")+
    (bands.length?bars(`Completion by number band — ${lineLabel}`,"Owned against the number of models in that band. Where the collection is strong and where it thins out.",bands):"")+
    bars(`Completion by marque — ${lineLabel}`,"Owned against how many that marque has in this line. Top 20 by how many you own.",mk)+
    (scaleWorth?bars(`What you own, by scale · ${lineLabel}`,
      "Counted at the exact ratio each release states, never rounded into a neighbouring one: a range built to fill a box has a ratio that follows the real vehicle, so a 1:62 is a 1:62 and not a small 1:64. Owned against how many of that scale are in this line.",
      scales):"")+
    (cond.length?bars("Condition of what you own","Share of your collection in each grade.",cond):"")+
    (rel.length?bars("Released vs pre-order","Pre-orders are not yet buyable, so they are not really missing.",rel):"")+
    bars("Overall",`Your ${lineLabel} against the catalogue. Owned is what is on the shelf${comingP.length?"; on the way is counted on its own line":""}.`,owners)+
    rarityInsights(myP, lineLabel);
}



function rarityInsights(mine, lineLabel){
  const scored = mine.filter(d => d.rr != null && !d.k);
  if(!scored.length) return "";
  const dist = RAR_BANDS.map(b => [b, scored.filter(d => rarBand(d.rr) === b).length, scored.length])
                        .filter(r => r[1] > 0);
  const top = [...scored].sort((a, b) => b.rr - a.rr).slice(0, 5);
  const unknown = mine.filter(d => d.rr == null && !d.k).length;
  const line = d => {
    const r = rarityOf(d);
    return `<div class="evrow"><b>${esc(d.t || d.n)}</b>
      <i>${r.s} / 100 &middot; ${esc(r.b)} &middot; confidence ${esc(r.c.toLowerCase())}
      &middot; ${esc(brandsOf(d)[0] || "")}</i></div>`;
  };
  

  const distinct = new Set(top.map(d => d.rr)).size;
  const allSame = top.length > 1 && distinct === 1;
  const heading = allSame ? "The rarest you own \u2014 all level"
                : top.length < 5 ? `The ${top.length === 1 ? "one" : top.length} rarest you own`
                : "The five rarest you own";
  const note = allSame
    ? `Every one of these scores the same, because they rest on the same single piece of evidence. There is nothing on file that would put one above another, and inventing a difference would be worse than showing none.`
    : `Rarity is about the release, not about what it cost you or what it is worth now.`;
  return bars(`Rarity of what you own \u2014 ${lineLabel}`,
      `How scarce the releases on your shelf appear to be. ${scored.length} of your ${mine.filter(d=>!d.k).length} cars have evidence on file`
      + (unknown ? `; ${unknown} have none, which is not the same as being common \u2014 it means nobody publishes how many were made.` : "."),
      dist)
    + `<div class="panel"><h3>${heading}</h3>
       <p class="sub">${note}</p>
       ${top.map(line).join("")}</div>`;
}

 





async function photosOf(d){
  const shots = [];
  const first = imgSrc(d);
  if(first) shots.push(first);
  

  try{ await extraLoad(); }catch(e){}
  const inline = (typeof EXTRA!=="undefined") ? EXTRA[d.n] : null;
  if(inline) for(const u of inline) if(!shots.includes(u)) shots.push(u);
  return shots;
}
async function gallery(d, firstSrc){
  const strip = document.getElementById("strip"), big = document.getElementById("bigimg");
  if(!strip || !big) return;
  const shots = await photosOf(d);
  if(shots.length < 2){ strip.remove(); return; }
  

  strip.innerHTML = shots.map((u,i)=>
    `<button class="thumb${i===0?" on":""}" data-i="${i}" aria-label="Photo ${i+1} of ${shots.length}${i===0?", showing":""}" aria-pressed="${i===0}"><img loading="lazy" decoding="async" referrerpolicy="no-referrer" src="${u}" alt=""></button>`).join("");
  strip.onclick = e => {
    const b = e.target.closest(".thumb"); if(!b) return;
    [...strip.children].forEach(x=>{ x.classList.toggle("on", x===b);
      x.setAttribute("aria-pressed", x===b ? "true" : "false"); });
    big.removeAttribute("data-remote");           
    big.src = shots[+b.dataset.i];
  };
}



var OPEN_AT = -1;
function openCard(i){
  const d=current[i]; if(!d) return;
  OPEN_AT = i;
  

  if(typeof needDetail === "function" && typeof detailKnown === "function" && !detailKnown(d))
    needDetail([d]).then(() => { if(OPEN_AT === i && current[i] === d) openCard(i); });
  const _ms=imgSrc(d);
  const img=_ms?`<div class="big"><img id="bigimg" decoding="async" referrerpolicy="no-referrer" src="${_ms}" data-remote="${remoteSrc(d)}" alt="${esc(photoAlt(d))}"></div>
                 <div class="strip" id="strip"></div>`:"";
  const _bs=brandsOf(d);
  const rows=[
    

    

    

    ["Catalogue number", d.nocode
      ? (brandsOf(d).includes("Hot Wheels")
          ? `<span class='est'>not the maker's code \u2014 Mattel prints a toy number on the card, but the shops do not list it, so this key is built from the listing</span>`
          : brandsOf(d).includes("Tomica")
          ? `<span class='est'>Tomica prints a box number rather than a code per release, and re-uses it \u2014 so this key is built from the name</span>`
          

          : brandsOf(d).includes("HKM")
          ? `<span class='est'>HKM prints no number on any release and no source carries one \u2014 this key is built here from the model and the colour, so it is ours and not HKM's</span>`
          : `<span class='est'>not confirmed \u2014 no shop prints a number for this one</span>`)
      : esc(d.n)],
    

    

    ...(d.pnum ? [["Number on the box", "No." + esc(d.pnum)
        + (d.pkind === "assortment"
           ? ` <span class='est'>the number the maker prints on the assortment, which holds more than one car. There is no number that means this one on its own</span>`
           : d.pkind === "item"
           ? ` <span class='est'>the maker's own number for this exact release</span>`
           : brandsOf(d).includes("Tomica")
           ? ` <span class='est'>Tomica re-uses its numbers, so this one has belonged to other cars in other years</span>`
           : d.yr ? ` <span class='est'>where this one sat in the ${d.yr} run</span>`
           : ` <span class='est'>printed on the packaging, not a product code</span>`)]] : []),
    

    ...(d.cat_years && d.cat_years.length ? (() => {
        const newest = Math.max.apply(null, d.cat_years.map(Number));
        const now = (typeof CAT_YEAR_NOW === "object" && CAT_YEAR_NOW)
                    ? CAT_YEAR_NOW[d.br] : null;
        return [["In the catalogue", d.cat_years.join(" and ")
          + (now && newest < now
             ? ` <span class='est'>and not in the ${now} one, so it has been dropped from the range</span>`
             : ` <span class='est'>the maker's own catalogues this number appears in</span>`)]];
      })() : []),
    

    ...(() => { const v = scaleOf(d); return v.s
      ? [["Scale", esc(v.s) + ` <span class='est'>${esc(scaleWhy(d, v))}</span>`]]
      : [["Scale", `<span class='est'>not stated \u2014 no source gives a ratio for this one, so none is invented here</span>`]]; })(),
    ...(d.era ? [["Vehicle from", esc(d.era)]] : []),
     
    ["Marque", esc(d.m||"") + (() => {
      const PAR = (typeof MARQUE_PARENT === "object" && MARQUE_PARENT) ? MARQUE_PARENT : {};
      if(PAR[d.m]) return ` <span class='est'>a ${esc(PAR[d.m])} sub-brand</span>`;
      if(d.mk === "constructor") return ` <span class='est'>the team that built this car, not a maker of road cars</span>`;
      return "";
    })()],
    

    

    ...(() => {
      const _mk = (brandsOf(d)[0] || null);
      if(!taxLevels(_mk).some(l => l.k === "seg")) return [];
      const _k = segOf(d);
      return _k
        ? [[taxLabel(_mk,"seg","Segment"), esc(segName(_k))
            + ` <span class='est'>${esc(segNote(_k))}</span>`]]
        : [[taxLabel(_mk,"seg","Segment"),
            `<span class='est'>not placed${segWhy(d.br) ? " \u2014 " + esc(segWhy(d.br)) : ""}</span>`]];
    })(),
    ...(d.fam ? [[taxLabel(brandsOf(d)[0]||null,"fam","Family"), esc(d.fam) + (d.hwpos ? " \u00b7 " + esc(d.hwpos) : "")
        + ` <span class='est'>the group it belongs to inside ${esc(d.br||"its range")}</span>`]] : []),
    

    ...attrsOf(d).map(c => { const a = attrDef(c) || {}; const _w = attrWhy(d, c);
      return [a.lab || c, `<b>yes</b> <span class='est'>${esc(a.note||"")}</span>`
        + (_w ? `<br><span class='est'>on file because ${esc(_w)}</span>` : "")]; }),
    

    [_bs.length>1?"Catalogues":"Catalogue",
     _bs.join(" and ")+(_bs.length>1?" <span class='est'>one release, counted once in the overall collection</span>":"")],
    

    ...(() => { const G = (typeof BRAND_GROUP === "object" && BRAND_GROUP) ? BRAND_GROUP : {};
       
      const up = [...new Set(_bs.map(b => G[b]).filter(Boolean))];
      if(up.length){
        const sibs = Object.keys(G).filter(b => up.includes(G[b]) && !_bs.includes(b));
        return [["Part of", esc(up.join(" and "))
          + ` <span class='est'>${esc(_bs.join(" and "))} is its arm`
          + (sibs.length ? `, alongside ${esc(sibs.join(" and "))}` : "") + `</span>`]];
      }
       
      const kids = Object.keys(G).filter(b => _bs.includes(G[b]));
      if(kids.length)
        return [["Also makes", esc(kids.join(" and "))
          + " <span class='est'>a separate catalogue out of the same house</span>"]];
      return [];
    })(),
    ...(d.br && !_bs.includes(d.br) ? [["Range",d.br]] : []),
    ...(d.cb ? [["Collaboration", esc(d.cb)
        + (d.cbnote ? ` <span class='est'>${esc(d.cbnote)}</span>` : "")]] : []),
    ["Release status",d.s?"Released":"Pre-order"],
    ["In your collection",d.o===1?("Yes"+(d.c?" — "+d.c.toLowerCase():"")):d.o===2?"On the way":"No"],
    

    

    ["Market value", !d.v ? `<span class='est'>not recorded</span>` : gbp(d.v)+` <span class='est'>${
      d.vs ? (/secondary/i.test(d.vs) ? "from secondary listings"
             : /^(the|a) /.test(d.vs) ? d.vs : "live retail at "+d.vs)
      : (d.sh&&d.sh.length) ? "the cheapest of "+d.sh.length+" tracked shop"+(d.sh.length>1?"s":"")
      : "no source on file \u2014 carried forward from an earlier import and not a figure anybody has checked"}</span>`],
  ];
  

  if(d.o){
    const _p=paidOf(d), _v=valOf(d)||d.v||0, _gaps=paidGaps(d);
    

    const _kind = priceSource(d);
    rows.push([_kind === "retail" ? "Retail price" : "Price paid", _p
      ? priv(_p)+privIf(_v && _kind !== "retail" ?`  <span class='est'>${_v-_p>=0?"+":"−"}${money(Math.abs(_v-_p))}</span>`:"")
        +privIf(_gaps?`  <span class='est'>${_gaps} ${_gaps===1?"copy has":"copies have"} no price</span>`:"")
      : "not recorded in your app"]);
    if(_kind === "retail")
      rows.push(["About that price",
        ((typeof RRP!=="undefined" && RRP[d.n]) ? RRP[d.n] + ". " : "")
        + "No receipt for this one exists anywhere, so this is what it sold for new. It is not counted as money you spent."]);
  }
  if(d.x) rows.push(["Variant",esc(d.x.charAt(0).toUpperCase()+d.x.slice(1)+(d.xn?" — "+d.xn:""))]);
  const MON=["","January","February","March","April","May","June","July",
             "August","September","October","November","December"];
  if(d.yr) rows.push(["Released",(d.mo?MON[d.mo]+" ":"")+d.yr]);
  if(d.cyr) rows.push(["The car",`${d.cyr} <span class='est'>the year of the car itself, as the maker names it, not the year this model was sold</span>`]);
  if(d.eta && !d.s){
    const QN={Q1:"January to March",Q2:"April to June",Q3:"July to September",Q4:"October to December"};
    const m=String(d.eta).match(/^(Q[1-4])\s+(\d\d)$/);
    const late=etaLate(d.eta);
    rows.push([late?"Was due":"Due", d.eta + (m ? ` <span class='est'>(${QN[m[1]]} 20${m[2]})</span>` : "")
      + (late ? " <span class='est'>that estimate has passed, so it is running late</span>"
              : " <span class='est'>the shops' estimate, not a confirmed date</span>")]);
  }
  

  if(d.lot) rows.push(["Limited to", (isNaN(+d.lot) ? esc(String(d.lot)) : (+d.lot).toLocaleString()+" pieces")]);
  if(d.hand && /^(LHD|RHD|LHD\/RHD)$/i.test(d.hand.trim())) rows.push(["Drive",d.hand]);
  if(d.col) rows.push(["Colour",d.col]);
  

  

  const _rel = relatedOf(d.n);
  if(_rel.length){
    const kinds = [...new Set(_rel.map(r => r.r))];
    for(const k of kinds){
      const mine = _rel.filter(r => r.r === k);
      const say = RELATED_SAYS[k] || ["Related releases", ""];
      const list = mine.map(r => {
        const o = byNum.get(r.n);
        const mark = !o ? "" : o.o === 1 ? ' <span class="pill p-own">yours</span>'
                   : o.o === 2 ? ' <span class="pill p-ord">on the way</span>' : "";
        return `<button type="button" class="chip relgo" data-n="${esc(r.n)}">${esc(r.n)}</button>${mark}`;
      }).join(" ");
      rows.push([say[0], list + (say[1] ? ` <span class='est'>${esc(say[1])}</span>` : "")]);
    }
  }
  if(d.jp) rows.push(["Name on the box",`<span class="jpname">${esc(d.jp)}</span>`]);
  if(d.jan) rows.push(["Barcode",`<span class="mono">${esc(d.jan)}</span> <span class='est'>the JAN printed on the box, as Tomytec publishes it</span>`]);
  if(d.tspec) rows.push(["Special series",`Limited Vintage special series <span class='est'>a numbered release outside the ordinary run</span>`]);
  if(d.tnote) rows.push(["About this name",`<span class='est'>${esc(d.tnote)}</span>`]);
  if(d.snote) rows.push(["About this name",`<span class='est'>${esc(d.snote)}</span>`]);
  if(d.tvar) rows.push(["How Tomytec tells it apart",`<span class='est'>${esc(d.tvar)}</span>`]);
  

  if(d.tn) rows.push(["Tuner or livery",esc(d.tn)]);
  

  if(d.ms){
    const M = d.ms, bits = [];
    if(M.season) bits.push(M.season);
    if(M.series) bits.push(M.series);
    if(bits.length) rows.push(["Raced in", esc(bits.join(" \u00b7 "))]);
    

    if(M.event) rows.push(["Race", esc(M.event)
      + ((M.event_also || []).length
          ? " <span class='est'>also called " + esc((M.event_also || []).join(", ")) + "</span>" : "")]);
    

    if(M.crew && M.crew.length > 1)
      rows.push([M.crew.length > 2 ? "Drivers" : "Crew", esc(M.crew.join(" \u00b7 "))
        + (M.no != null ? " <span class='est'>car " + esc(M.no) + "</span>" : "")]);
    else if(M.driver)
      rows.push(["Driver", esc(M.driver) + (M.no != null ? " \u00b7 car " + esc(M.no) : "")]);
    else if(M.no != null) rows.push(["Car number", esc(M.no)]);
    if(M.team) rows.push(["Entered by", esc(M.team)]);
    

    const car = [M.builder, M.chassis].filter(Boolean).join(" ");
    if(car) rows.push(["Car", esc(car)]);
    if(M.livery) rows.push(["Race livery", esc(M.livery)]);
    if(M.result) rows.push(["Result", esc(M.result)]);
     
    if(M.role) rows.push(["At the event as", esc(M.role)]);
    

    if(M.read)
      rows.push(["How the race is known", "<span class='est'>read from the maker's own "
        + "name for this release, not from a catalogue that states the entry</span>"]);
  }
  if(d.pack) rows.push(["Packaging", esc(d.pack)]);
  

  if(d.ownnote) rows.push(["Your row", "<span class='est'>" + esc(d.ownnote) + "</span>"]);
  if(d.cols && d.cols.length)
    rows.push(["Colours issued", esc(d.cols.join(", "))
      + " <span class='est'>the colours the maker's own catalogue prints against this number</span>"]);
  

  if(d.ver === "discovered")
    rows.push(["Verified", "<span class='est'>Not yet. This release has been found"
      + (d.src_name ? " on " + esc(d.src_name) : "")
      + ", but the maker does not list it, so nothing here is treated as confirmed.</span>"]);
  if(d.src_name)
    rows.push(["Source", esc(d.src_name)
      + (d.src_type ? " <span class='est'>" + esc(d.src_type) + "</span>" : "")]);
  if(d.user) rows.push(["Row added by hand",
      "the manufacturer catalogue does not carry this number, so it was typed in here. "
      + "<span class='est'>It is the only kind of row you can delete.</span>"]);
  if(d.ex) rows.push(["Exclusive to",
      `${esc(d.ex.c==="?"?"market not recorded":d.ex.c)} <span class='est'>${esc(d.ex.w)}</span>`]);
  if(d.bond) rows.push([brandsOf(d).includes("Mini GT")?"007 line":"James Bond",
      brandsOf(d).includes("Mini GT")
        ? `yes <span class='est'>one of the ${DATA.filter(x=>x.bond&&!x.k&&brandsOf(x).includes("Mini GT")).length} Mini GT James Bond cars</span>`
        : `yes <span class='est'>a James Bond film car, but not part of the Mini GT 007 line</span>`]);
  

  if(d.chase) rows.push(["Chase exists",
      (d.chase === 1 || d.chase === true
        ? `<b>Yes</b>`
        : `<b>Yes</b> \u2014 described as \u201c${esc(String(d.chase))}\u201d`)
      + ` <span class='est'>a chase version of this model was made. This is not a claim that you have one, and it does not mean this row IS the chase.</span>`]);

  

  const _r = rarityOf(d);
  if(_r) rows.push(["Rarity",
      `<b>${_r.s} / 100</b> ${esc(_r.b)} <span class='est'>confidence ${esc(_r.c.toLowerCase())}</span>`
    + ` <button class="whybtn" data-why="${esc(d.n)}" type="button">Why this score?</button>`
    + `<br><span class='est'>how scarce the release appears to be, which is not what it is worth</span>`]);

  const _sc = (typeof scarcityOf === "function") ? scarcityOf(d) : null;
  if(_sc && _sc.state === "ok"){
    const pct = _sc.pct >= 10 ? _sc.pct.toFixed(0) : _sc.pct.toFixed(2);
    rows.push(["Collector scarcity here",
      (_sc.owners === 0
        ? `<b>No MYMINI164 collector owns one</b>`
        : `<b>${_sc.score} / 100</b> <span class='est'>owned by ${_sc.owners} of ${_sc.relevant.toLocaleString()} ${esc(_sc.brand)} collectors here, ${pct}%</span>`)
      + `<br><span class='est'>measured among MYMINI164 members, not a figure about world production. Sample: ${esc(_sc.quality.toLowerCase())}</span>`]);
  }else if(_sc && _sc.state === "withheld"){
    

    rows.push(["Collector scarcity here",
      `<span class='est'>fewer than ${SCAR.cfg.min_owners} MYMINI164 collectors own one, which is too few to put a number on without it being about a person rather than about the release</span>`]);
  }else if(_sc && _sc.state === "insufficient"){
    rows.push(["Collector scarcity here",
      `<span class='est'>not enough ${esc(_sc.brand||"")} collectors here yet to say anything honest about how uncommon this is (${_sc.relevant} so far)</span>`]);
  }else if(typeof AUTH !== "object" || !AUTH){
    

    rows.push(["Collector scarcity here",
      `<span class='est'>this copy is yours alone, so there is no collector population to measure against. The figure lives in the shared app, where it counts how many members own one \u2014 which is a different question from how many were made.</span>`]);
  }

  const _mk = (typeof marketOf === "function") ? marketOf(d) : null;
  if(_mk && _mk.value_typical != null){
    

    rows.push(["Estimated market value",
      `<b>${gbp(_mk.value_low)}\u2013${gbp(_mk.value_high)}</b>`
      + ` <span class='est'>typical ${gbp(_mk.value_typical)}, from ${_mk.usable_sample} completed sale${_mk.usable_sample===1?"":"s"}, confidence ${esc(_mk.confidence||"low")}</span>`
      + `<br><span class='est'>what one has actually changed hands for. Asking prices are recorded separately and are not part of this.</span>`]);
  }
  if(_mk && _mk.demand && _mk.demand !== "unknown"){
    rows.push(["Market demand",
      `<b>${esc(DEMAND_WORD[_mk.demand] || _mk.demand)}</b> <span class='est'>confidence ${esc(_mk.demand_confidence||"low")}</span>`
      + `<br><span class='est'>how hard people are currently trying to get one, which is not the same as what it costs</span>`]);
  }
  

  const _mysets=setsOf(d);
  if(_mysets.length) rows.push(["Part of", _mysets.map(x=>{
      const sp=setProgress(x)||{have:0,n:(x.parts||[]).length};
      return `<b>${x.n}</b> ${(x.t||"").replace(/"/g,"&quot;")} <span class='est'>you have ${sp.have} of ${sp.n}</span>`;
    }).join("<br>")]);
  if(d.k){
    const sp=setProgress(d);
    if(sp) rows.push(["Set progress",
      `<b>${sp.have} of ${sp.n}</b>${sp.coming?` <span class='est'>and ${sp.coming} on the way</span>`:""}`]);
  }
  

  if(d.iss && d.iss.length) rows.push([d.iss.length===1?"Issued as":"Issued as",
      d.iss.map(i=>{
        const what = [i.t || "", i.h ? i.h.toUpperCase() : "", i.c || ""]
          .map(x=>String(x).trim()).filter(Boolean).join(" \u00b7 ");
        const run = i.lot != null && i.lot !== "" && !isNaN(+i.lot)
          ? ` <span class='est'>${(+i.lot).toLocaleString()} made</span>`
          : (i.lot ? ` <span class='est'>${esc(String(i.lot))}</span>` : "");
        return `<b>-${esc(i.s)}</b>${what?" "+esc(what):""}${run}`;
      }).join("<br>")]);
  const PROV={mfr:["Manufacturer listing","high"],marque:["Manufacturer, marque page only","high"],
              set:["Manufacturer set contents","high"],shop:["Recovered from a retailer","medium"],
              you:["You told me","high"],shopcat:["Retailer catalogue","medium"],
              sheet:["Your master spreadsheet","high"]};
  if(d.p && PROV[d.p]) rows.push(["Where this record came from",
      `${PROV[d.p][0]} <span class='est'>confidence ${PROV[d.p][1]}</span>`]);
  if(d.fs) rows.push(["First seen at a UK shop",
      `${esc(fmtMonth(d.fs))} <span class='est'>when Modelmatic first listed it, not the factory release date</span>`]);
  

  if(d.ord){
    const o=d.ord, all=(typeof ORDERS!=="undefined"&&ORDERS[o.id])?ORDERS[o.id]:null;
    

    rows.push([o.st==="received"?"Arrived in":"On the way in",
      `<b>${esc(o.shop)}${o.noref?" purchase":" order #"+esc(o.id)}</b> <span class='est'>placed ${fmtDate(o.date)}</span>`
      + (all?`<br><span class='est'>${all.lines.length} item${all.lines.length===1?"":"s"} in that order${privIf(", "+money(all.total)+" in all")}</span>`:"")
      + (o.st==="received"?"":`<br><span class='est'>counted as on the way, not as part of the collection, until you mark it arrived</span>`)]);
    if(o.pd!=null) rows.push(["Price on the order", priv(o.pd)+(o.q>1?` <span class='est'>each, ${o.q} ordered</span>`:"")]);
  }
  

  if(d.src) rows.push(["Bought from",esc(d.src)]);
  if(d.note) rows.push(["Your note",esc(d.note)]);
  

  const _extra = (typeof EXTRA!=="undefined" && EXTRA[d.n]) ? EXTRA[d.n] : [];
  const _main = imgSrc(d);
  const _nshots = new Set([_main, ..._extra].filter(Boolean)).size;
  const _only = _nshots===1 ? " Only one photo on file, so there is no gallery to swipe." : "";
  if(typeof PHOTOSRC!=="undefined" && PHOTOSRC[d.n])
    rows.push(["Photo","Sourced from "+PHOTOSRC[d.n]+"."+_only]);
  else if(_only && imgSrc(d) && !d.imgfrom) rows.push(["Photo",_only.trim()]);
  else if(d.imgfrom) rows.push(["Photo", d.imgfrom==="MGTS0016"
    ? "MINI GT never sold these twenty separately and never photographed them separately, so the set photo is shown. Every car is in it, roof numbers up, and this one is #"+(((d.t||"").match(/#(\d+)/)||[])[1]||"?")+"."
    : "No photo of this car on its own, so the set's photo is shown."]);
  else if(!detailKnown(d)) rows.push(["Photo","Still arriving."]);
  else if(!d.i && !imgSrc(d)) rows.push(["Photo","Not on the manufacturer's listing, and no photo found yet."]);
  

  else if(d.i && !imgSrc(d)) rows.push(["Photo",
    "There is a photo of this one at the shop, but a page published on claude.ai cannot load pictures from other sites. "
    + "<span class='est'>The copy saved on your Mac shows it.</span>"]);
  

  if(typeof PHOTOSHARED!=="undefined" && PHOTOSHARED[d.n])
    rows.push(["Photo shared","The shop used one picture for this and "+
      PHOTOSHARED[d.n].map(x=>(byNum.get(x)||{}).t||x).join(", ")+
      ", so it may not be this exact car."]);
  if(d.k) rows.push(["Set",(d.parts||[]).length
      ? `${d.parts.length} cars: ${d.parts.join(", ")}. The set itself counts as nothing; each car counts as one.`
      : "The set itself counts as nothing; the cars inside it each count as one. No contents list published for this one."]);
  const shops=d.sh.length
    ? `<h3 style="margin:20px 0 0;font-size:14px">Where to buy</h3><div class="shops">`+
      [...d.sh].sort((a,b)=>a[1]-b[1]).map(([nm,pr,url])=>
        `<a class="shop" href="${url}" target="_blank" rel="noopener"><span class="nm">${nm}</span><span class="pr">${shopMoney(pr,"GBP")}${CUR!=="GBP"?`<span class='est'> ≈ ${money(pr)}</span>`:""}</span><span class="go">open ↗</span></a>`).join("")+`</div>`
    : `<h3 style="margin:20px 0 6px;font-size:14px">Where to buy</h3><p class="sub" style="font-size:12.5px;color:var(--tx2);margin:0">None of the ${SHOPN} tracked shops has this in stock. It is an eBay hunt.</p>`;
  const shopnote = d.x && d.sh.length
    ? `<p class="sub" style="font-size:12px;color:var(--tx2);margin:6px 0 0">These listings are for the standard release. Yours is the ${d.x}, which trades well above them.</p>` : "";
  

  const _bs2=brandsOf(d);
  const head=`<div class="mhead">
      <div class="mtag" style="--bc:${brandColour(d)}">${esc(_bs2[0])}${_bs2.length>1?` <span>+${_bs2.length-1}</span>`:""}</div>
      <div class="mono mnum">${d.nocode?"number not confirmed":esc(d.n)}</div>
      <h2>${d.noname
        ? (d.jp ? `${esc(d.jp)} <span class="est">\u2014 the maker's own name</span>`
                : `<span class="est">name not recorded</span>`)
        : esc(d.t)}</h2>
      ${d.noname && d.nonamewhy ? `<p class="sub">${esc(d.nonamewhy)}</p>` : ""}
      <div class="mchips">
        ${scalePill(d)}
        ${d.m?`<span class="pill p-series">${esc(d.m)}</span>`:""}
        ${d.br&&!_bs2.includes(d.br)?`<span class="pill p-series">${esc(d.br)}</span>`:""}
        ${d.hand&&/^(LHD|RHD|LHD\/RHD)$/i.test(String(d.hand).trim())?`<span class="pill p-series">${esc(d.hand.trim().toUpperCase())}</span>`:""}
        ${d.o===1?'<span class="pill p-own">in your collection</span>':d.o===2?'<span class="pill p-ord">on the way</span>':""}
        ${d.w&&!d.o?`<span class="pill p-want">${["","want","priority","grail"][d.w]}</span>`:""}
        ${d.xc?'<span class="pill p-canc">cancelled</span>':""}
      </div>
    </div>`;
  $("#modal").innerHTML=img+`<div class="body"><button class="close" id="x" aria-label="Close">Close</button>
    ${head}</div>`;
  const _body=$("#modal").querySelector(".body");
  _body.insertAdjacentHTML("beforeend", collectionPanel(d));
  _body.insertAdjacentHTML("beforeend",
    `<div class="mdet"><h3 class="mdh">Details</h3>
     <dl class="dl">${rows.map(([a,b])=>`<dt>${a}</dt><dd>${b}</dd>`).join("")}</dl>${shops}${shopnote}</div>`);
  gallery(d, _ms);
  

  _body.addEventListener("click", e => {
    const b = e.target.closest(".relgo"); if(!b) return;
    const n = b.dataset.n; const row = byNum.get(n); if(!row) return;
    close();
    brand = "__all"; line = "__all"; view = "all";
    q = n; const box = document.getElementById("q"); if(box) box.value = n;
    if(typeof fillLines === "function") fillLines();
    if(typeof paintBrands === "function") paintBrands();
    [...document.querySelectorAll("#tabs button")].forEach(x => x.classList.toggle("on", x.dataset.v === "all"));
    recount(); render();
    const at = current.findIndex(x => x.n === n);
    if(at > -1) openCard(at);
  });
  openModal(); $("#x").onclick=close;
  wirePanel(d);
}

 
const TAGS=["chase","blister","Mijo exclusive","Kaido exclusive","error","signed","damaged box","loose"];
function copyRow(cp, i){
  const tags=(cp.x||"").split(",").map(s=>s.trim()).filter(Boolean);
  const opt=(v,l,sel)=>`<option value="${v}" ${sel?"selected":""}>${l}</option>`;
  return `<div class="copy" data-i="${i}">
    <div class="top">
      <span class="lbl">Copy ${i+1}</span>
      <select class="c_cond">
        ${["","SEALED","MINT","GOOD","FAIR"].map(c=>opt(c,c||"condition?",cp.c===c)).join("")}
      </select>
      <input class="c_paid" type="number" min="0" step="0.01" placeholder="paid" value="${cp.pd!=null?cp.pd:""}">
      <input class="c_val" type="number" min="0" step="0.01" placeholder="worth" value="${cp.v!=null?cp.v:""}">
      <button class="rm" title="Remove this copy">×</button>
    </div>
    <div class="tags">${TAGS.map(x=>
      `<span class="tag ${tags.includes(x)?"on":""}" data-x="${x}">${x}</span>`).join("")}</div>
  </div>`;
}

function collectionPanel(d){
  const cps=copiesOf(d);
  return `<div class="cpanel" id="cpanel">
    <h3>Your copies</h3>
    ${d.k?setNote(d):""}
    <div class="seg" id="segstatus">
      <button data-o="1" class="${d.o===1?"on":""}">✓ I have it</button>
      <button data-o="2" class="${d.o===2?"on":""}">On the way</button>
      <button data-o="0" class="${!d.o?"on":""}">Not mine</button>
    </div>
    <div id="wantbox" style="${d.o?"display:none":""}">
      <p class="sub" style="font-size:12px;color:var(--tx3);margin:10px 0 7px;line-height:1.5">
        Not yours yet. Set a ceiling and any shop at or under it is flagged on the card.</p>
      <div class="seg want" id="segwant">
        <button data-w="0" class="${!d.w?"on":""}">Not chasing</button>
        <button data-w="1" class="${d.w===1?"on":""}">Want</button>
        <button data-w="2" class="${d.w===2?"on":""}">Priority</button>
        <button data-w="3" class="${d.w===3?"on":""}">Grail</button>
      </div>
      <div class="fields" style="margin-top:10px">
        <div><label>Most you would pay</label>
          <input id="p_max" type="number" step="0.01" min="0" value="${d.mx!=null?(d.mx*rateFor(CUR)).toFixed(2):""}" placeholder="leave blank for market value"><span class="sub" style="font-size:11px;color:var(--tx3)">in ${CUR}</span></div>
      </div>
    </div>
    <div id="detail" style="${d.o===1?"":"display:none"}">
      <p class="sub" style="font-size:12px;color:var(--tx3);margin:0 0 9px;line-height:1.5">
        One row per physical car. Two of the same model with one a chase is two rows,
        each with its own condition, price and markings. Leave paid or worth blank to
        use the model's own figures.</p>
      <div class="copies" id="copies">${cps.map(copyRow).join("")}</div>
      <button class="addcopy" id="addcopy">+ Add another copy</button>
      <div class="fields" style="margin-top:12px">
        <div><label>Bought from</label><input id="p_src" value="${esc(d.src)}" placeholder="Gadsby's, eBay…"></div>
        <div style="grid-column:1/-1"><label>Note</label><input id="p_note" value="${esc(d.note)}" placeholder="anything you want to remember"></div>
      </div>
    </div>
    <div class="saverow">
      <button class="btn pri" id="p_save">Save</button>
      <span class="saved" id="p_ok">Saved</span>
      <span class="sub" id="p_sum" style="font-size:12px;color:var(--tx3);margin-left:auto"></span>
    </div>
  </div>`;
}

function setNote(d){
  const parts=(d.parts||[]).map(n=>byNum.get(n)).filter(Boolean);
  if(!parts.length) return `<p class="sub" style="margin:-4px 0 10px;font-size:12.5px;color:var(--gold);line-height:1.5">
    This is a set. It stays marked as yours but counts as nothing on its own - the cars inside it each count as one.
    I do not have a contents list for this one, so add the numbers from the box yourself with <b>+ Add</b>.</p>`;
  const have=parts.filter(p=>p.o===1).length, coming=parts.filter(p=>p.o===2).length;
  const got = have===parts.length ? `You have all ${parts.length}.`
            : have||coming ? `You have ${have}${coming?`, with ${coming} on the way`:""}.`
            : "You have none of them yet.";
  return `<div style="margin:-4px 0 12px">
    <p class="sub" style="font-size:12.5px;color:var(--gold);line-height:1.5;margin:0 0 8px">
      This is a set, so it counts as nothing on its own. The ${parts.length} cars inside it each count as one.
      ${got} Whatever you pick here is applied to all ${parts.length}.</p>
    <div class="tagrow" style="margin:0">${parts.map(p=>
      `<span class="tag ${p.o===1?"on":""}" style="cursor:default;${p.o===2?"border-color:var(--order);color:var(--order)":""}"
        title="${(p.t||"name not recorded").replace(/"/g,"&quot;")}${p.o===2?" - on the way":p.o?"":" - not yours"}">${p.n}</span>`).join("")}</div>
  </div>`;
}

function wirePanel(d){
  const g=id=>document.getElementById(id);
  let o=d.o||0;
  let cps=copiesOf(d).map(c=>({c:c.c||"", x:c.x||"", pd:c.pd, v:c.v}));
  if(o===1 && !cps.length) cps=[{c:"",x:"",pd:undefined,v:undefined}];

  let w=d.w||0;
  const paint=()=>{
    [...g("segstatus").children].forEach(b=>{
      const on = +b.dataset.o===o;
      b.classList.toggle("on", on);
      b.setAttribute("aria-pressed", on ? "true" : "false");   
    });
    g("detail").style.display = o===1 ? "" : "none";
    const wb=g("wantbox"); if(wb) wb.style.display = o ? "none" : "";
    const sw=g("segwant"); if(sw) [...sw.children].forEach(b=>{
      const on = +b.dataset.w===w;
      b.classList.toggle("on", on);
      b.setAttribute("aria-pressed", on ? "true" : "false");
    });
    g("copies").innerHTML = cps.map(copyRow).join("");
    const t={n:cps.length};
    g("p_sum").textContent = o===1
      ? `${cps.length} ${cps.length===1?"copy":"copies"}`
      : o===2 ? "on the way" : "";
  };
  if(g("segwant")) g("segwant").onclick=e=>{
    const b=e.target.closest("button"); if(!b) return; w=+b.dataset.w; paint();
  };
  g("segstatus").onclick=e=>{
    const b=e.target.closest("button[data-o]"); if(!b) return;
    o=+b.dataset.o;
    if(o===1 && !cps.length) cps=[{c:"",x:"",pd:undefined,v:undefined}];
    paint();
  };
  g("addcopy").onclick=()=>{
    const last=cps[cps.length-1];
    cps.push({c:last?last.c:"", x:"", pd:undefined, v:undefined});   
    paint();
  };
  g("copies").addEventListener("click", e=>{
    const row=e.target.closest(".copy"); if(!row) return;
    const i=+row.dataset.i;
    if(e.target.classList.contains("rm")){
      cps.splice(i,1); if(!cps.length) o=0; paint(); return;
    }
    const tag=e.target.closest(".tag");
    if(tag){
      const set=new Set((cps[i].x||"").split(",").map(s=>s.trim()).filter(Boolean));
      const x=tag.dataset.x;
      set.has(x) ? set.delete(x) : set.add(x);
      cps[i].x=[...set].join(", ");
      tag.classList.toggle("on", set.has(x));
    }
  });
  g("copies").addEventListener("change", e=>{
    const row=e.target.closest(".copy"); if(!row) return;
    const i=+row.dataset.i;
    if(e.target.classList.contains("c_cond")) cps[i].c=e.target.value;
    if(e.target.classList.contains("c_paid")) cps[i].pd=e.target.value===""?undefined:+e.target.value;
    if(e.target.classList.contains("c_val"))  cps[i].v =e.target.value===""?undefined:+e.target.value;
  });

  g("p_save").onclick=()=>{
    const clean=cps.map(c=>{
      const r={c:c.c||"", x:c.x||""};
      if(c.pd!=null) r.pd=c.pd;
      if(c.v!=null)  r.v=c.v;
      return r;
    });
    const first=clean[0]||{};
    

    patch(d.n, {
      o, cp: o?clean:[],
      q: o?clean.length:0,
      c: first.c||"",                       
      x: [...new Set(clean.flatMap(c=>(c.x||"").split(",").map(s=>s.trim()).filter(Boolean)))].join(", ")||undefined,
      src: g("p_src").value.trim()||undefined,
      note: g("p_note").value.trim()||undefined,
      w: o?0:w,                                   
      mx: (o||!g("p_max")||g("p_max").value==="")?undefined
           : +( +g("p_max").value / rateFor(CUR) ).toFixed(2)   
    });
    if(d.k && (d.parts||[]).length){
      for(const pn of d.parts){
        const p=byNum.get(pn); if(!p) continue;
        

        if(o===0){ if(p.o) patch(pn,{o:0}); }
        else if(o===2){ if(!p.o) patch(pn,{o:2, q:1, cp:[{c:"",x:""}]}); }
        else if(p.o!==1) patch(pn,{o:1, q:Math.max(1,qtyOf(p)||1),
                 cp:copiesOf(p).length?copiesOf(p):[{c:first.c||"",x:""}]});
      }
    }
    g("p_ok").classList.add("on");
    setTimeout(()=>g("p_ok").classList.remove("on"),1400);
    recount(); render();
    if(typeof paintBrands==="function") paintBrands();
     
    if(typeof toast==="function"){
      const nq=o?clean.length:0;
      toast(o===1 ? "Saved \u2014 "+d.n+" is in your garage"+(nq>1?" ("+nq+" copies)":"")
          : o===2 ? "Saved \u2014 "+d.n+" is on the way"+(nq>1?" ("+nq+" copies)":"")
          : w     ? "Saved \u2014 "+d.n+" is on your want list"
          :         "Saved \u2014 "+d.n+" is not in your collection", "good");
    }
  };
  paint();
}



let _lastFocus=null;
function openModal(){
  _lastFocus = document.activeElement;
  const m=$("#modal");
  $("#mask").classList.add("on");
  $("#mask").setAttribute("aria-hidden","false");
  dialogOpen(m, close, _lastFocus);
}
function close(){
  $("#mask").classList.remove("on");
  $("#mask").setAttribute("aria-hidden","true");
  OPEN_AT = -1;
  

  if(!dialogClose($("#modal")) && _lastFocus && document.contains(_lastFocus)){
    try{ _lastFocus.focus({preventScroll:true}); }catch(e){}
  }
  _lastFocus=null;
}
const closeModal=close;
$("#mask").onclick=e=>{ if(e.target.id==="mask") close(); };


$("#grid").onclick=e=>{
  const act=e.target.closest("[data-act]");
  const c=e.target.closest(".c"); if(!c) return;
  if(act){
    e.stopPropagation();
    const d=byNum.get(c.dataset.n); if(!d) return;
    if(act.dataset.act==="own"){
      const now=d.o===1?0:1;
      patch(d.n,{o:now, q:now?Math.max(1,qtyOf(d)):qtyOf(d)});
      toast(now?"Added to your garage \u2014 "+d.n:"Taken out of your garage \u2014 "+d.n, now?"good":"");
    }else{
      const now=d.w?0:1;
      patch(d.n,{w:now});
      toast(now?"On your want list \u2014 "+d.n:"Off your want list \u2014 "+d.n, now?"good":"");
    }
    act.classList.add("pulse");
    recount(); render(); if(typeof paintBrands==="function") paintBrands();
    return;
  }
  openCard(+c.dataset.i);
};
 
$("#grid").onkeydown=e=>{
  if(e.key!=="Enter"&&e.key!==" ") return;
  const c=e.target.closest(".c"); if(!c||e.target.closest("[data-act]")) return;
  e.preventDefault(); openCard(+c.dataset.i);
};

$("#value").onclick=e=>{
  const tr=e.target.closest(".panelwide tbody tr"); if(!tr) return;
  

  marque=tr.dataset.m; fillMarques(); $("#marque").value=marque;
  view="own"; [...$("#tabs").children].forEach(x=>x.classList.toggle("on",x.dataset.v==="own"));
  render(); window.scrollTo({top:0,behavior:"smooth"});
};
$("#tabs").onclick=e=>{ const b=e.target.closest("button"); if(!b)return;
  [...$("#tabs").children].forEach(x=>x.classList.toggle("on",x===b)); view=b.dataset.v;
  render(); if(typeof paintNav==="function"){ paintNav(); paintHero(); }
  

  if(typeof scrollTo==="function") scrollTo({top:0,behavior:"instant" in window?"auto":"auto"});
};


$("#q").oninput=e=>{ q=e.target.value.trim(); document.getElementById("qclear").classList.toggle("on",!!q);
  if(q && (view==="stats"||view==="value")){ setView("all"); return; }
  render(); paintFilters(); };
document.getElementById("qclear").onclick=()=>{ q=""; $("#q").value=""; document.getElementById("qclear").classList.remove("on"); $("#q").focus(); render(); };
