$("#sort").onchange=e=>{ sort=e.target.value; render(); };
$("#relonly").onclick=e=>{ relOnly=!relOnly; e.currentTarget.classList.toggle("on",relOnly); render(); };
$("#chaseonly").onclick=e=>{ chaseOnly=!chaseOnly; e.currentTarget.classList.toggle("on",chaseOnly); render(); };
