$("#chasehunt").onclick=e=>{ chaseHunt=!chaseHunt; e.currentTarget.classList.toggle("on",chaseHunt); render(); };
$("#collabonly").onclick=e=>{ collabOnly=!collabOnly; e.currentTarget.classList.toggle("on",collabOnly); render(); };
(function(){ const sc=document.getElementById("scalerow");
  if(sc) sc.onclick=e=>{
    const more=e.target.closest("button[data-scalemore]");
    if(more){ scaleShowAll=!scaleShowAll; fillScales(); return; }
    const b=e.target.closest("button[data-scale]"); if(!b) return;
    const k=b.dataset.scale;
    scalePick.has(k) ? scalePick.delete(k) : scalePick.add(k);
    

    fillSegments(); fillAttrs(); fillScales(); recount(); render(); paintFilters();
  }; })();
$("#nopreowned").onclick=e=>{ noPreowned=!noPreowned; e.currentTarget.classList.toggle("on",noPreowned); render(); };
$("#noboxes").onclick=e=>{ noBoxes=!noBoxes; e.currentTarget.classList.toggle("on",noBoxes); render(); };


(function mirrorChipState(){
  const ids = ["editmode","relonly","chaseonly","chaseexists","chasehunt",
               "collabonly","canctoggle","nopreowned","noboxes"];
  const els = ids.map(i=>document.getElementById(i)).filter(Boolean);
  const sync = el => { try{ el.setAttribute("aria-pressed", el.classList.contains("on") ? "true" : "false"); }catch(e){} };
  els.forEach(sync);
  if(typeof MutationObserver !== "function") return;
  const mo = new MutationObserver(ms => { for(const m of ms) sync(m.target); });
  els.forEach(el => mo.observe(el, {attributes:true, attributeFilter:["class"]}));
})();



