let imgFails=0, warned=false;
document.addEventListener("error", e=>{
  const im=e.target;
  if(!im || im.tagName!=="IMG" || im.dataset.failed) return;
  const wasLocal = im.src.indexOf("garage_images/")>-1;
  if(wasLocal){
    
    
    
    const step=(+im.dataset.ext||0)+1;
    if(step<IMG_EXT.length){
      im.dataset.ext=step;
      im.src=im.src.replace(/\.[^.\/]+$/,"."+IMG_EXT[step]);
      return;
    }
    if(im.dataset.remote){ const r=im.dataset.remote; im.removeAttribute("data-remote"); im.src=r; return; }
  }
  im.dataset.failed="1";
  
  
  if(!wasLocal || im.dataset.remote) imgFails++;
  const ph=im.parentNode;
  if(ph && ph.classList.contains("ph")) ph.innerHTML='<div class="noimg">photo unavailable</div>';
  

  else if(ph && ph.classList.contains("big")){
    ph.classList.add("noshot");
    ph.innerHTML='<div class="noimg">photo unavailable \u2014 it is hosted by the shop and needs an internet connection</div>';
  }
  if(imgFails>=25 && !warned){
    warned=true;
    document.getElementById("imgwarn").style.display="block";
  }
}, true);



