async function saveChanges(){
  const owned = DATA.filter(d=>d.o).map(d=>({
    n:d.n, t:d.t, br:d.br, m:d.m, q:qtyOf(d), c:d.c||"", pd:d.pd, v:d.v, x:d.x||"", user:d.user?1:0
  }));
  

  const ledger = {patches:{}, added:[...EDITS.added], removed:[...EDITS.removed]};
  const BASEBY = new Map(baseRows().map(d=>[d.n, d]));
  for(const d of DATA){
    

    if(d.user){ if(!ledger.added.some(r=>r.n===d.n)) ledger.added.push(Object.assign({n:d.n}, bodyOf(d))); continue; }
    const b = BASEBY.get(d.n); if(!b) continue;
    const diff = {};
    

    const blank = x => x===undefined || x===null || x==="" || x===0;
    for(const k of EDIT_FIELDS){
      const now = d[k], was = b[k];
      if(blank(now) && blank(was)) continue;
      if(k==="q" && now === (d.o?1:0) && blank(was)) continue;
      if(JSON.stringify(now===undefined?null:now) !== JSON.stringify(was===undefined?null:was)) diff[k]=now;
    }
    if(Object.keys(diff).length) ledger.patches[d.n]=diff;
  }
  const out = {
    

    format: "mini164-collection",
    formatVersion: 1,
    savedAt: new Date().toISOString(),
    note: "A snapshot of your collection. Restore it with the Load button, or hand it to Claude.",
    

    totals: {models: owned.length, pieces: owned.reduce((s,r)=>s+r.q,0),
             value: +DATA.reduce((s,d)=>s+valOf(d),0).toFixed(2),
             paid: +totalPaidOwned(DATA).toFixed(2),
             pricedAtRetail: +totalRetailStandIn(DATA).toFixed(2)},
    edits: ledger, owned
  };
  const _ok = await download("collection.json", JSON.stringify(out,null,1));
  dirty = false; markDirty();
   
  if(typeof toast==="function") toast(_ok===false
    ? "The browser would not save the backup"
    : "Backup saved \u2014 "+owned.length+" cars, "+out.totals.pieces+" pieces", _ok===false?"bad":"good");
}


function looksLikeBackup(j){
  if(!j || typeof j !== "object" || Array.isArray(j)) return false;
  const e = j.edits;
  if(!e || typeof e !== "object" || Array.isArray(e)) return false;
  const shapeOK = (e.patches === undefined || (e.patches && typeof e.patches === "object" && !Array.isArray(e.patches)))
    && (e.added === undefined || Array.isArray(e.added))
    && (e.removed === undefined || Array.isArray(e.removed));
  if(!shapeOK) return false;
  

  const hasLedger = (e.patches && Object.keys(e.patches).length)
                 || (Array.isArray(e.added) && e.added.length)
                 || (Array.isArray(e.removed) && e.removed.length);
  const hasOwned = Array.isArray(j.owned);
  return !!(hasLedger || hasOwned || j.savedAt || j.format);
}
function countEdits(ed){
  const e = normaliseEdits(ed);
  return Object.keys(e.patches).length + e.added.length + e.removed.length;
}
function loadChanges(file){
  const r = new FileReader();
  r.onerror = () => alert("That file could not be read from disk.");
  r.onload = async () => {
    let j = null;
    try{ j = JSON.parse(r.result); }
    catch(e){
      alert("That file is not readable as JSON, so nothing has been changed.\n\n" + e.message);
      return;
    }
    if(!looksLikeBackup(j)){
      alert("That does not look like a collection.json saved from this page, so nothing has been changed.");
      return;
    }
    const incoming = countEdits(j.edits), mineNow = countEdits(EDITS);
    const ownedNow = DATA.filter(d=>d.o).length;
    if(mineNow){
      const okGo = confirm(
        "Restoring replaces what is on this page.\n\n" +
        "On the page now: " + ownedNow + " models, " + mineNow + " change" + (mineNow===1?"":"s") + ".\n" +
        "In the file: " + (Array.isArray(j.owned) ? j.owned.length : "an unknown number of") +
        " models, " + incoming + " change" + (incoming===1?"":"s") +
        (j.savedAt ? ", saved " + String(j.savedAt).slice(0,10) : "") + ".\n\n" +
        "Replace what is here?");
      if(!okGo) return;
    }
    try{
      EDITS = normaliseEdits(j.edits);
      DATA.length = 0; baseRows().forEach(d=>DATA.push(JSON.parse(JSON.stringify(d))));
      reindex(); applyEdits();
      if(DB){ for(const n of new Set([...Object.keys(EDITS.patches), ...EDITS.added.map(x=>x.n), ...EDITS.removed])) queueWrite(n); }
      else { saveStore(); fsQueue(); }
      markDirty(); recount(); render();
      if(typeof paintFilters==="function"){ paintFilters(); paintNav(); paintDrawerCard(); }
      toast("Restored \u2014 " + DATA.filter(d=>d.o).length + " cars marked as yours", "good");
    }catch(e){
      alert("That file could not be applied, so nothing has been changed.\n\n" + e.message);
    }
  };
  r.readAsText(file);
}

 
