const SCAN = (()=>{
  const $$=id=>document.getElementById(id);
  const sheet=$$("scanmask"), stage=$$("scanstage"), vid=$$("scanvid"), msg=$$("scanmsg"),
        teach=$$("scanteach"), file=$$("scanfile");
  let stream=null, det=null, loop=0, lastMiss="";

  const say=(h,sub)=>{ msg.innerHTML = sub?`<b>${h}</b><br>${sub}`:h; };
  const hasDet = typeof window.BarcodeDetector!=="undefined";

  function learned(){
    const m={};
    DATA.forEach(d=>(d.bcs||[]).forEach(c=>m[c]=d.n));
    return m;
  }
  

  

  const NUMKEY=(()=>{ const m=new Map();
    DATA.forEach(d=>{ const k=String(d.n).toUpperCase().replace(/[^A-Z0-9]/g,""); if(!m.has(k)) m.set(k,d.n); });
    return m; })();
  function asProductCode(raw){
    const t=String(raw).toUpperCase().replace(/[^A-Z0-9]/g,"");
    if(!t) return null;
    if(NUMKEY.has(t)) return NUMKEY.get(t);
     
    const u=String(raw).toUpperCase().replace(/\s+/g,"");
    const pad=n=>String(parseInt(n,10)).padStart(3,"0");
    let c=null, mm;
    if((mm=u.match(/^PR-?640-?(\d{1,4})$/))) c="PR640"+pad(mm[1]);
    else if((mm=u.match(/^PR-?64-(\d{1,4})$/))) c="PR640"+pad(mm[1]);
    else if((mm=u.match(/^PRDC-?(\d{1,4})$/))) c="PRDC"+pad(mm[1]);
    else if((mm=u.match(/^PRE-?(\d{2,4})$/))) c="PRE"+pad(mm[1]);
    else if((mm=u.match(/^PRT-?(\d{2,4})$/))) c="PRT"+pad(mm[1]);
    else if((mm=u.match(/^(?:XCT-?)?([A-Z]{1,3}\d{1,3}-\d{1,3})$/))) c="XCT-"+mm[1];
    if(c && NUMKEY.has(c.replace(/[^A-Z0-9]/g,""))) return NUMKEY.get(c.replace(/[^A-Z0-9]/g,""));
    let m=t.match(/^(MGTS\d{4}|MGT\d{5}|KHMG\d{3})/);
    if(m) return m[1];
    m=t.match(/^(MGT|KHMG)0*(\d{1,5})$/);       
    if(m) return m[1]==="KHMG" ? "KHMG"+m[2].padStart(3,"0") : "MGT"+m[2].padStart(5,"0");
    return null;
  }
  function lookup(code){
    const p=asProductCode(code);
    if(p && byNum.get(p)) return p;
    const c=String(code).replace(/\D/g,"");
    if(!c) return null;
    const tries=[c, c.padStart(13,"0"), c.replace(/^0+/,"")];
    const L=learned();
    for(const t of tries){ if(BARCODES[t]) return BARCODES[t]; if(L[t]) return L[t]; }
    return null;
  }
  function found(code){
    const n=lookup(code);
    if(!n){ miss(code); return; }
    const d=byNum.get(n);
    if(!d){ miss(code); return; }
     
    if(typeof badgeAct==="function") badgeAct("scans", 1);
    stop(); close();
    

    q=""; $("#q").value=n; brand="__all"; line="__all";
    if(typeof clearCollections==="function") clearCollections();
    if(typeof fillLines==="function") fillLines();
      if(typeof paintBrands==="function") paintBrands();
    $("#line").value="__all";
    view="all"; [...$("#tabs").children].forEach(x=>x.classList.toggle("on",x.dataset.v==="all"));
    marque=""; relOnly=chaseOnly=chaseMade=chaseHunt=false;
    

    if(d.xc && !showCanc){ showCanc=true; $("#canctoggle").classList.add("on"); }
    fillMarques(); $("#marque").value="";
    collabOnly=false;
    scalePick.clear(); fillScales();
    $("#relonly").classList.remove("on"); $("#chaseonly").classList.remove("on");
    $("#chasehunt").classList.remove("on");
    $("#chaseexists").classList.remove("on"); $("#collabonly").classList.remove("on");
    q=n; recount(); render();
    const i=current.findIndex(x=>x.n===n);
    if(i>-1) openCard(i);
  }
  function miss(code){
    const p=asProductCode(code);
    if(p){   
      say(`No car numbered ${p}.`, "Check the code on the blister. If it is right, add it with <b>+ Add</b> in Edit mode and it joins the catalogue.");
      teach.innerHTML=""; return;
    }
    lastMiss=String(code).replace(/\D/g,"");
    if(lastMiss.length<8){ say(`${code} is not a barcode or a product code.`,
      "A barcode is 12 or 13 digits. A product code looks like MGT01208-L."); teach.innerHTML=""; return; }
    say(`Scanned ${lastMiss}`, "That barcode is not on file yet. Search for the car and it will be remembered.");
    teach.innerHTML=`<input id="scanfind" placeholder="Name or number of the car in your hand"
      style="width:100%;background:var(--bg2);border:1px solid var(--line);border-radius:10px;
      color:var(--tx);padding:9px 11px;font:500 14px/1 Inter,sans-serif"><div class="hits" id="scanhits"></div>`;
    const inp=$$("scanfind"); inp.focus();
    inp.oninput=()=>{
      const t=inp.value.trim().toLowerCase();
      const hits = t.length<2 ? [] : DATA.filter(d=>
        

        d.n.toLowerCase().includes(t) || (d.t||"").toLowerCase().includes(t)).slice(0,25);
      $$("scanhits").innerHTML = hits.map(d=>
        `<div class="hit" data-n="${d.n}"><img loading="lazy" decoding="async" referrerpolicy="no-referrer" src="${imgSrc(d)}" alt=""><span>${d.t?esc(d.t):(d.jp?esc(d.jp):"<i>name not recorded</i>")}<b>${esc(d.n)}</b></span></div>`).join("")
        || (t.length<2?"":`<p class="sub" style="font-size:12.5px;color:var(--tx3)">Nothing matches that.</p>`);
      $$("scanhits").querySelectorAll(".hit").forEach(el=>el.onclick=()=>{
        const d=byNum.get(el.dataset.n); if(!d) return;
        const bcs=[...new Set([...(d.bcs||[]), lastMiss])];
        patch(d.n, {bcs});
        say(`Noted.`, `${lastMiss} now points at <b>${d.n}</b>. Scanning it again will find it straight away.`);
        teach.innerHTML="";
        setTimeout(()=>found(lastMiss), 700);
      });
    };
  }

  async function decodeFrom(src){
    if(!hasDet) return null;
    try{
      det = det || new window.BarcodeDetector({formats:["ean_13","upc_a","ean_8","upc_e","code_128"]});
      const res = await det.detect(src);
      return res.length ? res[0].rawValue : null;
    }catch(e){ return null; }
  }

  async function startCamera(){
    if(!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia){
      say("This browser will not give the page a camera.", "Take a photo instead, or type the digits."); return;
    }
    if(!hasDet){
      say("This browser has no barcode reader built in.",
          "Safari and iOS do not ship one. Type the digits below, or open this page in Chrome.");
      return;
    }
    try{
      stream = await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:"environment"}}});
    }catch(e){
      const why = /NotAllowedError|SecurityError|Permission/i.test(String(e.name||e))
        ? "The camera is blocked here. On a published page the camera is often withheld from the frame, and the browser may also be refusing it."
        : String(e.message||e);
      say("No live camera.", why + " Take a photo instead, or type the digits.");
      return;
    }
    stage.classList.add("on");
    try{
      vid.srcObject=stream;
    }catch(e){
      stop();
      say("No live camera.", "The browser handed back a stream this page cannot show. Take a photo instead, or type the digits.");
      return;
    }
    await vid.play().catch(()=>{});
    say("Hold the barcode inside the frame.");
    const tick=async()=>{
      if(!stream) return;
      const code=await decodeFrom(vid);
      if(code){ found(code); return; }
      loop=requestAnimationFrame(()=>setTimeout(tick,120));
    };
    tick();
  }
  function stop(){
    if(loop) cancelAnimationFrame(loop), loop=0;
    if(stream){ stream.getTracks().forEach(t=>t.stop()); stream=null; }
    stage.classList.remove("on"); vid.srcObject=null;
  }
  function open_(){
    teach.innerHTML=""; $$("scantype").value=""; say("");
    sheet.classList.add("on");
    const n=Object.keys(BARCODES).length + Object.keys(learned()).length;
    $$("scancov").textContent = n.toLocaleString()+" barcodes on file. Anything missing, point at the car once and it is remembered.";
    startCamera();
    

    dialogOpen($$("scansheet"), close, $$("scanbtn"));
  }
  function close(){ stop(); sheet.classList.remove("on"); dialogClose($$("scansheet")); }

  file.onchange = async e => {
    const f=e.target.files[0]; e.target.value="";
    if(!f) return;
    if(!hasDet){ say("This browser has no barcode reader built in.",
      "Safari and iOS do not ship one, so a photo cannot be read here. Type the digits below."); return; }
    say("Reading the photo…");
    try{
      const bmp=await createImageBitmap(f);
      const code=await decodeFrom(bmp);
      if(code) found(code);
      else say("No barcode in that photo.", "Fill the frame with the barcode, hold steady, and try again.");
    }catch(err){ say("Could not read that photo.", String(err.message||err)); }
  };

  $$("scanbtn").onclick=open_;
  $$("scanx").onclick=close;
  sheet.onclick=e=>{ if(e.target.id==="scanmask") close(); };
  $$("scanphoto").onclick=()=>file.click();
  $$("scango").onclick=()=>{ const v=$$("scantype").value.trim(); if(v) found(v); };
  $$("scantype").onkeydown=e=>{ if(e.key==="Enter") $$("scango").click(); };
  return {open:open_, close, lookup, hasDet};
})();






