function badgeSlug(s){
  return String(s||"").toLowerCase().replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,"") || "x";
}
function badgeTierFor(step, steps){
  const t = ["steel","chrome","gold","platinum"];
  return t[Math.min(t.length-1, Math.round(step / Math.max(1, steps-1) * (t.length-1)))];
}

