const NAME_KEY = "m164-name";
const AVATAR_KEY = "m164-avatar";


const DEFAULT_NAME = (typeof SUPA === "object" && SUPA) ? "Collector" : "maccimalist";

function storedName(){
  try{ const n = localStorage.getItem(NAME_KEY); if(n && n.trim()) return n.trim(); }catch(e){}
  return "";
}


function displayName(){
  const A = (typeof AUTH === "object" && AUTH) ? AUTH : null;
  if(A && A.profile && A.profile.display_name && String(A.profile.display_name).trim())
    return String(A.profile.display_name).trim();
  const local = storedName();
  if(local) return local;
  if(A && A.me && A.me.email) return String(A.me.email).split("@")[0];
  return DEFAULT_NAME;
}
function avatarSrc(){
  try{ const a = localStorage.getItem(AVATAR_KEY); if(a && a.slice(0,11) === "data:image/") return a; }catch(e){}
  return "";
}
function initialsOf(n){
  const parts = String(n || "").trim().split(/[\s._-]+/).filter(Boolean);
  if(!parts.length) return "M164";
  if(parts.length === 1) return parts[0].slice(0,2).toUpperCase();
  return (parts[0][0] + parts[parts.length-1][0]).toUpperCase();
}
function avatarHTML(size, cls){
  const src = avatarSrc(), n = displayName();
  return src
    ? '<img class="av ' + (cls||"") + '" src="' + esc(src) + '" alt="" width="' + size + '" height="' + size + '">'
    : '<span class="av av-txt ' + (cls||"") + '" style="width:' + size + 'px;height:' + size + 'px;'
      + 'font-size:' + Math.round(size/2.9) + 'px" aria-hidden="true">' + esc(initialsOf(n)) + '</span>';
}



const AVATAR_PX = 192, AVATAR_CAP = 140000;
function readAvatar(file){
  return new Promise((resolve, reject) => {
    if(!file || !/^image\//.test(file.type||"")) return reject(new Error("That is not a picture."));
    if(file.size > 25e6) return reject(new Error("That picture is too large. Try one under 25 MB."));
    const fr = new FileReader();
    fr.onerror = () => reject(new Error("That picture could not be read."));
    fr.onload = () => {
      const im = new Image();
      im.onerror = () => reject(new Error("That picture could not be read."));
      im.onload = () => {
        try{
          const s = Math.min(im.width, im.height);
          const c = document.createElement("canvas");
          c.width = c.height = AVATAR_PX;
          const x = c.getContext("2d");
          x.imageSmoothingQuality = "high";
          x.drawImage(im, (im.width-s)/2, (im.height-s)/2, s, s, 0, 0, AVATAR_PX, AVATAR_PX);
          let out = c.toDataURL("image/jpeg", 0.82);
          if(out.length > AVATAR_CAP) out = c.toDataURL("image/jpeg", 0.6);
          if(out.length > AVATAR_CAP) return reject(new Error("That picture would not compress small enough."));
          resolve(out);
        }catch(e){ reject(new Error("That picture could not be processed.")); }
      };
      im.src = fr.result;
    };
    fr.readAsDataURL(file);
  });
}
function setAvatar(dataUrl){
  try{
    if(dataUrl) (typeof savePref === "function" ? savePref : (k,v)=>localStorage.setItem(k,v))(AVATAR_KEY, dataUrl);
    else localStorage.removeItem(AVATAR_KEY);
  }catch(e){ if(typeof toast === "function") toast("This browser would not store that picture."); return false; }
  paintIdentity();
  return true;
}


function setDisplayName(n){
  const v = String(n || "").trim().slice(0, 40);
  try{ if(v) (typeof savePref === "function" ? savePref : (k,x)=>localStorage.setItem(k,x))(NAME_KEY, v); else localStorage.removeItem(NAME_KEY); }catch(e){}
  const A = (typeof AUTH === "object" && AUTH) ? AUTH : null;
  if(A && A.me && typeof A.rename === "function") A.rename(v).catch(()=>{});
  paintIdentity();
  

  const nv = document.getElementById("a-nameval");
  if(nv) nv.textContent = v || "not set";
}

 
function paintIdentity(){
  const n = displayName();
  const who = document.getElementById("drwho");
  if(who) who.textContent = (typeof SUPA === "object" && SUPA) ? n : "@" + n;
  const av = document.getElementById("drav");
  if(av) av.innerHTML = avatarHTML(38);
  

  const mav = document.getElementById("meav");
  if(mav) mav.innerHTML = avatarHTML(30);
  const mnm = document.getElementById("menm");
  if(mnm) mnm.textContent = n;
  const mbt = document.getElementById("mebtn");
  if(mbt) mbt.setAttribute("aria-label", n + " — your profile");
  const since = document.getElementById("drsince");
  

  if(since) since.textContent = collectingSince() || "Collector";
  if(view === "me" && typeof drawProfile === "function") drawProfile();
  if(typeof paintHero === "function" && view === "me") paintHero();
}


function collectingSince(){
  const c = badgeCtx();
  if(!c.dates.length) return "";
  const m = c.dates[0].match(/^(\d{4})-(\d{2})/);
  if(!m) return "";
  const MON = ["January","February","March","April","May","June","July",
               "August","September","October","November","December"];
  return "Collecting since " + MON[+m[2]-1] + " " + m[1];
}



function profileFigures(c){
  const fig = (v, l, t) => '<div class="pfig"' + (t ? ' title="' + esc(t) + '"' : '') + '>'
    + '<b>' + v + '</b><i>' + esc(l) + '</i></div>';
  return '<div class="pfigs">'
    + fig(c.owned.toLocaleString(), "models", "different catalogue numbers on the shelf")
    + fig(c.pieces.toLocaleString(), "pieces", "every copy counted")
    + fig(c.ordered.toLocaleString(), "on the way")
    + fig(c.wanted.toLocaleString(), "want list")
    + fig(c.brandsOwnedCount.toLocaleString(), "catalogues")
    + fig(c.marquesOwnedCount.toLocaleString(), "marques")
    + '</div>';
}

function drawProfile(){
  const host = document.getElementById("profile"); if(!host) return;
  const c = badgeCtx();
  const s = badgeState();
  const earned = badgesEarned();
  const picked = showcaseIds().map(id => s.by[id]).filter(x => x && x.earned);
  const shown = (picked.length ? picked : earned.slice().sort((a,b) => {
      const A = (a.held && (a.held.on && a.held.on.by || a.held.on || a.held.at)) || "";
      const B = (b.held && (b.held.on && b.held.on.by || b.held.on || b.held.at)) || "";
      return String(B).localeCompare(String(A));
    })).slice(0, 3);

  

  let html = '<div class="pfhead">'
    + '<div class="pfav">' + avatarHTML(96) + '</div>'
    

    + '<div class="pfid"><b>' + esc(collectingSince() || "Collector") + '</b>'
    + '<i>' + esc(c.owned.toLocaleString() + " models across "
        + c.brandsOwnedCount + (c.brandsOwnedCount === 1 ? " catalogue" : " catalogues")) + '</i></div>'
    + '<button type="button" class="iconbtn" id="pfedit">Edit profile</button>'
    + '</div>';

  html += profileFigures(c);

   
  html += '<section class="pfsec"><h3>Badges <span class="pfcount">' + earned.length.toLocaleString()
        + ' of ' + s.list.length.toLocaleString() + '</span></h3>';
  html += shown.length
    ? '<div class="pfbadges">' + shown.map(st =>
        '<button type="button" class="pfbadge" data-badge="' + esc(st.def.id) + '">'
        + badgeArt(st.def, st, 84)
        + '<b>' + esc(st.def.name) + '</b></button>').join("")
      + '</div><p class="pfnote">'
      + (picked.length ? 'Your chosen three. Change them in the badges room.'
                       : 'Your three most recent. Pick your own in the badges room.')
      + '</p>'
    : '<p class="pfnote">No badges yet. They arrive on their own as the collection grows.</p>';
  html += '<button type="button" class="iconbtn" id="pfbadgego">Open the badges room</button></section>';

  

  const cats = [...c.brandOwned.entries()]
    .map(([b, n]) => ({b, n, all: c.brandAll.get(b) || 0}))
    .sort((x, y) => y.n - x.n);
  if(cats.length){
    html += '<section class="pfsec"><h3>Catalogues <span class="pfcount">' + cats.length + '</span></h3>'
      + '<div class="pfbars">' + cats.map(x => {
        const pc = x.all ? Math.min(100, Math.round(x.n / x.all * 100)) : 0;
        return '<button type="button" class="pfbar" data-brand="' + esc(x.b) + '">'
          + '<span class="pfbar-l">' + esc(x.b) + '</span>'
          + '<span class="pfbar-t"><i style="width:' + pc + '%"></i></span>'
          + '<span class="pfbar-n">' + x.n.toLocaleString() + '<em> / ' + x.all.toLocaleString() + '</em></span>'
          + '</button>';
      }).join("") + '</div></section>';
  }

  

  const marques = [...c.marqueOwned.entries()]
    .filter(([m]) => m && m !== "Other")
    .sort((a, b) => b[1] - a[1]).slice(0, 18);
  if(marques.length){
    html += '<section class="pfsec"><h3>Marques <span class="pfcount">'
      + c.marquesOwnedCount.toLocaleString() + '</span></h3><div class="pfchips">'
      + marques.map(([m, n]) => '<button type="button" class="chip" data-marque="' + esc(m) + '">'
          + esc(m) + ' <b>' + n + '</b></button>').join("")
      + '</div></section>';
  }

  

  const recent = DATA.filter(d => d.o === 1 && !d.k && !d.xc && d.ord
                                  && /^\d{4}-\d{2}-\d{2}$/.test(d.ord.date || ""))
    .sort((a, b) => String(b.ord.date).localeCompare(String(a.ord.date)))
    .slice(0, 8);
  if(recent.length){
    html += '<section class="pfsec"><h3>Latest on the shelf</h3><div class="pflatest">'
      + recent.map(d => {
        const src = (typeof imgSrc === "function") ? imgSrc(d) : "";
        return '<button type="button" class="pflat" data-num="' + esc(d.n) + '">'
          + (src ? '<img loading="lazy" src="' + esc(src) + '" alt="">'
                 : '<span class="pflat-no" aria-hidden="true"></span>')
          + '<b>' + esc(d.t || d.n) + '</b>'
          + '<i>' + esc(fmtDate(d.ord.date)) + '</i></button>';
      }).join("") + '</div></section>';
  }

  html += '<p class="pffoot">Your profile is yours alone: nothing here is shared with anybody '
        + 'else, and no price, total or valuation appears on it. What the collection cost lives '
        + 'in the portfolio.</p>';

  host.innerHTML = html;

  const ed = document.getElementById("pfedit");
  if(ed) ed.onclick = () => openProfileEditor();
  const go = document.getElementById("pfbadgego");
  if(go) go.onclick = () => setView("badge");
  if(!host._wired){
    host._wired = true;
    host.addEventListener("click", e => {
      const bg = e.target.closest("[data-badge]");
      if(bg && typeof openBadge === "function"){ openBadge(bg.dataset.badge); return; }
      const br = e.target.closest("[data-brand]");
      if(br){ brand = br.dataset.brand; line = "__all";
        if(typeof refreshBrands === "function") refreshBrands();
        setView("own");
        if(typeof fillLines === "function") fillLines();
        if(typeof paintBrands === "function") paintBrands();
        recount(); render(); return; }
      const mq = e.target.closest("[data-marque]");
      if(mq){ marque = mq.dataset.marque;
        const sel = document.getElementById("marque"); if(sel) sel.value = marque;
        brand = "__all"; line = "__all"; setView("own");
        if(typeof paintBrands === "function") paintBrands();
        recount(); render(); return; }
      

      const cd = e.target.closest("[data-num]");
      if(cd && typeof byNum !== "undefined"){
        const d = byNum.get(cd.dataset.num); if(!d) return;
        q = d.n; const qi = document.getElementById("q"); if(qi) qi.value = d.n;
        brand = "__all"; line = "__all"; marque = "";
        setView("all"); recount(); render();
        setTimeout(() => { if(typeof current !== "undefined" && current.length) openCard(0); }, 80);
      }
    });
  }
}



function openProfileEditor(){
  

  setTimeout(() => {
    const menu = document.getElementById("skinmenu");
    const btn = document.getElementById("skinbtn");
    if(menu && !menu.classList.contains("on") && btn) btn.click();
    paintProfileEditor();
    setTimeout(() => { const f = document.getElementById("pf-name"); if(f){ f.focus(); f.select(); } }, 60);
  }, 0);
}
function paintProfileEditor(){
  const av = document.getElementById("pf-av");
  if(av) av.innerHTML = avatarHTML(46);
  const f = document.getElementById("pf-name");
  if(f && document.activeElement !== f) f.value = storedName() || displayName();
  const rm = document.getElementById("pf-clear");
  if(rm) rm.hidden = !avatarSrc();
}
(function wireProfileEditor(){
  const f = document.getElementById("pf-name");
  const save = document.getElementById("pf-save");
  const file = document.getElementById("pf-file");
  const pick = document.getElementById("pf-pick");
  const clear = document.getElementById("pf-clear");
  const msg = document.getElementById("pf-msg");
  const say = (t, bad) => { if(msg){ msg.textContent = t || ""; msg.className = "pf-msg" + (bad ? " bad" : ""); } };
  if(save && f) save.onclick = () => {
    const v = f.value.trim();
    if(v.length > 40){ say("That name is too long. Forty characters at most.", true); return; }
    setDisplayName(v);
    say(v ? "Saved." : "Cleared.");
  };
  if(f) f.onkeydown = e => { if(e.key === "Enter"){ e.preventDefault(); save && save.click(); } };
  if(pick && file) pick.onclick = () => file.click();
  if(file) file.onchange = async e => {
    const x = e.target.files && e.target.files[0]; e.target.value = "";
    if(!x) return;
    say("Reading that picture…");
    try{
      const url = await readAvatar(x);
      if(setAvatar(url)){ paintProfileEditor(); say("Saved."); }
    }catch(err){ say(String(err.message || err), true); }
  };
  if(clear) clear.onclick = () => { setAvatar(""); paintProfileEditor(); say("Picture removed."); };
  const btn = document.getElementById("skinbtn");
  if(btn) btn.addEventListener("click", () => setTimeout(paintProfileEditor, 20), {passive:true});
})();



(function profileBoot(){
  const me = document.getElementById("drme");
  if(me) me.onclick = () => { setView("me"); if(typeof closeDrawer === "function") closeDrawer(); };
  

  const mb = document.getElementById("mebtn");
  if(mb) mb.onclick = () => { setView("me"); if(typeof closeDrawer === "function") closeDrawer(); };
  paintIdentity();
  paintProfileEditor();
})();




(function(){
  if(!(typeof AUTH === "object" && AUTH)) return;

   
   
  async function rpc(name, args){
    return AUTH.restJSON("/rpc/" + name, { method:"POST", body: JSON.stringify(args || {}) });
  }
  const one = r => (Array.isArray(r) ? (r[0] || null) : r);
  const many = r => (Array.isArray(r) ? r : (r == null ? [] : [r]));

  

  

  const E = (typeof esc === "function") ? esc : (s => String(s == null ? "" : s)
    .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;").replace(/'/g, "&#39;"));
  const say = (m, k) => { if(typeof toast === "function") toast(m, k); };
  const g = id => document.getElementById(id);

   
  function day(d){
    if(!d) return "";
    const m = String(d).match(/^(\d{4})-(\d{2})-(\d{2})/);
    if(!m) return String(d);
    const MON = ["January","February","March","April","May","June","July",
                 "August","September","October","November","December"];
    return (+m[3]) + " " + MON[(+m[2]) - 1] + " " + m[1];
  }
  function span(a, b){
    if(!a) return "Date not announced";
    if(!b || b === a) return day(a);
    const A = a.split("-"), B = b.split("-");
    if(A[0] === B[0] && A[1] === B[1]) return (+A[2]) + " to " + day(b);
    return day(a) + " to " + day(b);
  }
  function ago(ts){
    if(!ts) return "";
    const s = (Date.now() - new Date(ts).getTime()) / 1000;
    if(s < 90) return "just now";
    if(s < 5400) return Math.round(s / 60) + " minutes ago";
    if(s < 129600) return Math.round(s / 3600) + " hours ago";
    return Math.round(s / 86400) + " days ago";
  }
  

  function who(r){
    return E((r && (r.display_name || r.username)) || "A collector");
  }
  function handle(r){ return r && r.username ? "@" + E(r.username) : ""; }
  

  const SAFE_AVATAR = /^(?:https:\/\/|data:image\/(?:png|jpeg|jpg|gif|webp|avif);base64,)/i;
  function avatarUrl(u){
    const v = String(u == null ? "" : u).trim();
    if(!SAFE_AVATAR.test(v)) return "";
    return v.replace(/["'()\\<>\s]/g, c => "%" + c.charCodeAt(0).toString(16).padStart(2, "0"));
  }
  function avatar(r, size){
    const s = size || 40;
    const url = avatarUrl(r && r.avatar_url);
    const initial = ((r && (r.display_name || r.username)) || "?").trim().charAt(0).toUpperCase();
    if(url) return `<span class="soc-av" style="width:${s}px;height:${s}px;background-image:url('${url}')"></span>`;
    return `<span class="soc-av soc-av-t" style="width:${s}px;height:${s}px;font-size:${Math.round(s*0.42)}px">${E(initial)}</span>`;
  }

   
  

  function makeRoom(id, label){
    let el = g(id);
    if(el) return el;
    el = document.createElement("section");
    el.id = id; el.setAttribute("aria-label", label);
    el.style.cssText = "display:none;padding:18px 0 60px";
    const main = document.querySelector("main.wrap");
    const empty = g("empty");
    if(main) main.insertBefore(el, empty || null);
    return el;
  }
  makeRoom("club", "Community");
  makeRoom("news", "News and events");

  if(typeof DEST !== "undefined" && Array.isArray(DEST)){
    DEST.push(
      {v:"club", t:"Community", s:"Collectors, rankings and friends", c:"var(--acc)",
       i:'<circle cx="9" cy="8.6" r="3.2"/><path d="M3 19c0-3.1 2.7-5 6-5s6 1.9 6 5"/><path d="M16 5.4a3.2 3.2 0 0 1 0 6.3"/><path d="M17.4 14.3c2.2.6 3.6 2.2 3.6 4.7"/>'},
      {v:"news", t:"News", s:"What the makers have announced", c:"var(--b-tarmac)",
       i:'<path d="M4 5h13v14H5a1 1 0 0 1-1-1z"/><path d="M17 9h3v8a2 2 0 0 1-2 2"/><path d="M7 8h7M7 11h7M7 14h4"/>'}
    );
  }
  const tabs = g("tabs");
  if(tabs){
    for(const [v, label] of [["club","Community"], ["news","News"]]){
      if(tabs.querySelector(`[data-v="${v}"]`)) continue;
      const b = document.createElement("button");
      b.dataset.v = v; b.textContent = label;
      tabs.appendChild(b);
    }
  }

   
  

  const CSS = `
  .soc-wrap{max-width:980px;margin:0 auto}
  .soc-sub{display:flex;gap:6px;flex-wrap:wrap;margin:0 0 18px;border-bottom:1px solid var(--line);padding-bottom:10px}
  .soc-sub button{appearance:none;border:1px solid transparent;background:transparent;color:var(--tx2);
    font:inherit;font-size:13.5px;font-weight:600;padding:8px 13px;border-radius:9px;cursor:pointer;min-height:38px}
  .soc-sub button:hover{background:var(--card)}
  .soc-sub button.on{background:var(--card);border-color:var(--line);color:var(--tx)}
  .soc-card{border:1px solid var(--line);background:var(--card);border-radius:13px;padding:14px 16px;margin:0 0 10px}
  .soc-row{display:flex;align-items:center;gap:12px}
  .soc-row .soc-grow{flex:1;min-width:0}
  .soc-row b{display:block;font-size:14.5px;line-height:1.3;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
  .soc-row i{display:block;font-style:normal;color:var(--tx2);font-size:12.5px;line-height:1.5;margin-top:2px}
  .soc-av{display:inline-block;border-radius:50%;background-size:cover;background-position:center;
    background-color:color-mix(in srgb,var(--acc) 18%,var(--card));flex:none}
  .soc-av-t{display:inline-flex;align-items:center;justify-content:center;font-weight:700;color:var(--tx)}
  .soc-act{display:flex;gap:7px;flex-wrap:wrap;flex:none}
  .soc-btn{appearance:none;border:1px solid var(--line);background:var(--bg);color:var(--tx);font:inherit;
    font-size:12.5px;font-weight:600;padding:7px 12px;border-radius:9px;cursor:pointer;min-height:36px}
  .soc-btn:hover{border-color:var(--acc)}
  .soc-btn.pri{background:var(--acc);border-color:var(--acc);color:#fff}
  .soc-btn.warn{color:var(--bad,#c0392b)}
  .soc-btn[disabled]{opacity:.55;cursor:default}
  .soc-none{color:var(--tx2);font-size:13.5px;line-height:1.6;padding:16px 2px}
  .soc-h{font-size:12px;letter-spacing:.06em;text-transform:uppercase;color:var(--tx2);margin:22px 0 8px;font-weight:700}
  .soc-h:first-child{margin-top:0}
  .soc-in{width:100%;box-sizing:border-box;border:1px solid var(--line);background:var(--bg);color:var(--tx);
    font:inherit;font-size:14px;padding:10px 12px;border-radius:10px;min-height:42px}
  .soc-sel{border:1px solid var(--line);background:var(--bg);color:var(--tx);font:inherit;font-size:13px;
    padding:8px 10px;border-radius:9px;min-height:38px}
  .soc-rank{display:flex;align-items:center;gap:12px;padding:11px 14px;border-bottom:1px solid var(--line)}
  .soc-rank:last-child{border-bottom:0}
  .soc-rank.me{background:color-mix(in srgb,var(--acc) 9%,transparent)}
  .soc-pos{font-variant-numeric:tabular-nums;font-weight:700;width:2.4em;text-align:right;color:var(--tx2);flex:none}
  .soc-val{font-variant-numeric:tabular-nums;font-weight:700;flex:none}
  .soc-note{color:var(--tx2);font-size:12.5px;line-height:1.6;margin:10px 0 0}
  .soc-pill{display:inline-block;border:1px solid var(--line);border-radius:999px;padding:2px 9px;
    font-size:11.5px;font-weight:700;color:var(--tx2);margin:0 6px 0 0}
  .soc-news{display:flex;gap:14px;align-items:flex-start}
  .soc-news img{width:104px;height:78px;object-fit:cover;border-radius:9px;flex:none;background:var(--bg)}
  .soc-set{display:flex;align-items:flex-start;gap:12px;padding:13px 0;border-bottom:1px solid var(--line)}
  .soc-set:last-child{border-bottom:0}
  .soc-set .soc-grow b{display:block;font-size:14px}
  .soc-set .soc-grow i{display:block;font-style:normal;color:var(--tx2);font-size:12.5px;line-height:1.55;margin-top:3px}
  /* THE IDENTITY IS THE BUTTON. A name and a face are what somebody presses to open a
     person, so they are a real control with a focus ring and a hit area, and there is no
     second button beside them saying the same thing in words. */
  .soc-id{appearance:none;border:0;background:transparent;color:inherit;font:inherit;text-align:left;
    display:flex;align-items:center;gap:12px;flex:1;min-width:0;padding:4px;margin:-4px;border-radius:11px;cursor:pointer}
  .soc-id:hover{background:color-mix(in srgb,var(--acc) 8%,transparent)}
  .soc-id:focus-visible{outline:2px solid var(--acc);outline-offset:2px}
  .soc-id b{display:block;font-size:14.5px;line-height:1.3;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
  .soc-id i{display:block;font-style:normal;color:var(--tx2);font-size:12.5px;line-height:1.5;margin-top:2px}
  .soc-chip-c{display:inline-block;margin-left:7px;padding:1px 7px;border-radius:999px;font-size:10.5px;
    font-weight:700;letter-spacing:.04em;text-transform:uppercase;vertical-align:middle;
    color:var(--acc);border:1px solid color-mix(in srgb,var(--acc) 45%,transparent);
    background:color-mix(in srgb,var(--acc) 10%,transparent)}
  .soc-link{appearance:none;border:0;background:transparent;color:var(--tx2);font:inherit;font-size:inherit;
    padding:0;cursor:pointer;text-decoration:underline;text-underline-offset:2px}
  .soc-link:hover{color:var(--tx)}
  .soc-link:focus-visible{outline:2px solid var(--acc);outline-offset:2px;border-radius:4px}
  .soc-n{display:inline-block;min-width:1.5em;margin-left:5px;padding:0 5px;border-radius:999px;
    background:color-mix(in srgb,var(--acc) 16%,transparent);font-size:11px;font-weight:700}
  @media (max-width:560px){
    .soc-news img{width:74px;height:56px}
    .soc-row{flex-wrap:wrap}
    .soc-act{width:100%}
  }`;
  { const st = document.createElement("style"); st.textContent = CSS; document.head.appendChild(st); }

  

  

  const CLUB_TABS = [
    ["people",  "Find collectors"],
    ["friends", "People"],
    ["rank",    "Rankings"],
    ["feed",    "Activity"],
    ["privacy", "Privacy"]
  ];
  let clubTab = "people";
   
  let peopleList = "friends";
  let feedScope = "all";
  let CREATOR = null;
  

  const st = {
    q: "", rankMetric: "score", rankBrand: "",
    newsScope: "you", newsCat: "", eventsWhen: "upcoming"
  };

  

  async function creator(){
    if(CREATOR === null){
      try{ CREATOR = (await rpc("creator_id", {})) || ""; }catch(_){ CREATOR = ""; }
    }
    return CREATOR;
  }

  function clubShell(){
    return `<div class="soc-wrap">
      <div class="soc-sub" id="clubsub">${CLUB_TABS.map(([k, l]) =>
        `<button type="button" data-k="${k}"${k === clubTab ? ' class="on"' : ""}>${E(l)}</button>`).join("")}</div>
      <div id="clubbody"><p class="soc-none">Loading.</p></div>
    </div>`;
  }

  function drawClub(){
    const room = g("club"); if(!room) return;
    room.innerHTML = clubShell();
    g("clubsub").onclick = e => {
      const b = e.target.closest("button[data-k]"); if(!b) return;
      clubTab = b.dataset.k;
      [...g("clubsub").children].forEach(x => x.classList.toggle("on", x === b));
      paintClub();
    };
    paintClub();
  }

  

  async function into(host, work){
    const el = (typeof host === "string") ? g(host) : host;
    if(!el) return;
    el.innerHTML = `<p class="soc-none">Loading.</p>`;
    try{
      el.innerHTML = await work();
    }catch(err){
      el.innerHTML = `<div class="soc-card"><b>That did not load.</b>
        <p class="soc-note">${E(err && err.message ? err.message : String(err))}</p>
        <div class="soc-act" style="margin-top:10px"><button type="button" class="soc-btn" data-retry="1">Try again</button></div></div>`;
      const r = el.querySelector("[data-retry]");
      if(r) r.onclick = () => into(el, work);
    }
  }

  function paintClub(){
    const body = g("clubbody"); if(!body) return;
    if(clubTab === "people")  return into(body, viewPeople);
    if(clubTab === "friends") return into(body, viewMyPeople);
    if(clubTab === "rank")    return into(body, viewRank);
    if(clubTab === "feed")    return into(body, viewFeed);
    if(clubTab === "privacy") return into(body, viewPrivacy);
  }

   
  

  function creatorChip(p){
    return p && p.is_creator ? '<span class="soc-chip-c" title="This is the account that made MYMINI164">Creator</span>' : "";
  }
  function identity(p, size){
    return `<button type="button" class="soc-id" data-open="${E(p.user_id)}">
      ${avatar(p, size || 44)}
      <span class="soc-grow"><b>${who(p)}${creatorChip(p)}</b><i>${handle(p)}</i></span></button>`;
  }
  function followBtn(p){
    if(p.friend_state === "self") return "";
    return p.i_follow
      ? `<button type="button" class="soc-btn" data-unfollow="${E(p.user_id)}">Following</button>`
      : `<button type="button" class="soc-btn" data-follow="${E(p.user_id)}">Follow</button>`;
  }
  function friendBtn(p){
    const s = p.friend_state;
    if(s === "self")     return "";
    if(s === "friends")  return `<button type="button" class="soc-btn" disabled>Friends</button>`;
    if(s === "sent")     return `<button type="button" class="soc-btn" disabled>Asked</button>`;
    if(s === "received") return `<button type="button" class="soc-btn pri" data-accept-from="${E(p.user_id)}">Accept</button>`;
    return `<button type="button" class="soc-btn" data-ask="${E(p.user_id)}">Add friend</button>`;
  }
  function personRow(p, actions){
    return `<div class="soc-card"><div class="soc-row">
      ${identity(p)}<span class="soc-act">${actions === undefined ? followBtn(p) + friendBtn(p) : actions}</span>
      </div></div>`;
  }

  async function searchInto(host){
    const rows = many(await rpc("find_collectors", { q: st.q || null, limit_n: 30, offset_n: 0 }));
    return rows.length
      ? rows.map(p => personRow(p)).join("")
      : `<p class="soc-none">Nobody by that name. Try part of a name, a handle, or a make
         somebody collects.</p>`;
  }

  async function viewPeople(){
    const list = await searchInto();
    setTimeout(() => {
      const box = g("socq");
      if(!box) return;
      box.value = st.q;
      box.oninput = () => {
        st.q = box.value;
        clearTimeout(box._t);
        box._t = setTimeout(() => into("clubresults", searchInto), 300);
      };
    }, 0);
    return `<p class="soc-h">Find a collector</p>
      <input class="soc-in" id="socq" type="search" placeholder="A name, a handle, or a make they collect" maxlength="60">
      <p class="soc-note">Every collector here can be found. What they own is a separate
        question and stays theirs: finding somebody does not open their collection.</p>
      <div id="clubresults" style="margin-top:16px">${list}</div>`;
  }

   
  const PEOPLE_LISTS = [["friends","Friends"],["requests","Requests"],
                        ["following","Following"],["followers","Followers"]];

  async function viewMyPeople(){
    const me = AUTH.me && AUTH.me.id;
    const [fr, asks, fo, fers] = await Promise.all([
      rpc("my_friends", {}),
      rpc("my_friend_requests", {}),
      rpc("following_of", { owner: me, limit_n: 100, offset_n: 0 }),
      rpc("followers_of", { owner: me, limit_n: 100, offset_n: 0 })
    ]);
    const friends = many(fr), reqs = many(asks), following = many(fo), followers = many(fers);
    const inc = reqs.filter(r => r.direction === "in");
    const counts = { friends: friends.length, requests: reqs.length,
                     following: following.length, followers: followers.length };
    

    if(inc.length && peopleList === "friends") peopleList = "requests";

    const picker = `<div class="soc-sub" id="peoplesub" style="border:0;padding:0;margin:0 0 14px">${
      PEOPLE_LISTS.map(([k, l]) => `<button type="button" data-p="${k}"${k === peopleList ? ' class="on"' : ""}>${
        E(l)}${counts[k] ? ' <span class="soc-n">' + counts[k] + '</span>' : ""}</button>`).join("")}</div>`;

    let body = "";
    if(peopleList === "friends"){
      body = friends.length
        ? friends.map(p => personRow(Object.assign({ friend_state: "friends" }, p),
            (p.i_follow
              ? `<button type="button" class="soc-btn" data-unfollow="${E(p.user_id)}">Following</button>`
              : `<button type="button" class="soc-btn" data-follow="${E(p.user_id)}">Follow</button>`)
            + `<button type="button" class="soc-btn" data-compare="${E(p.user_id)}">Compare</button>`
            + `<button type="button" class="soc-btn warn" data-unfriend="${E(p.user_id)}">Remove</button>`)).join("")
        : `<p class="soc-none">No friends yet. Find a collector and ask; they decide.</p>`;
    } else if(peopleList === "requests"){
      const out = reqs.filter(r => r.direction === "out");
      body = `<p class="soc-h">Asked you</p>` + (inc.length
        ? inc.map(p => personRow(Object.assign({ user_id: p.other_id }, p),
            `<button type="button" class="soc-btn pri" data-yes="${E(p.id)}">Accept</button>
             <button type="button" class="soc-btn" data-no="${E(p.id)}">Decline</button>`)).join("")
        : `<p class="soc-none">Nothing waiting.</p>`)
        + `<p class="soc-h">You asked</p>` + (out.length
        ? out.map(p => personRow(Object.assign({ user_id: p.other_id }, p),
            `<button type="button" class="soc-btn" data-cancel="${E(p.id)}">Cancel</button>`)).join("")
        : `<p class="soc-none">You have not asked anybody.</p>`)
        + `<p class="soc-note">Declining is quiet: the person who asked is told the request is
           no longer outstanding, not that it was refused, and cannot ask again for thirty days.</p>`;
    } else if(peopleList === "following"){
      body = following.length
        ? following.map(p => personRow(p,
            `<button type="button" class="soc-btn" data-unfollow="${E(p.user_id)}">Following</button>` + friendBtn(p))).join("")
        : `<p class="soc-none">You are not following anybody yet.</p>`;
      body += `<p class="soc-note">Following is one way round and asks nothing of the other
        person. It does not open a collection they keep for friends.</p>`;
    } else {
      body = followers.length
        ? followers.map(p => personRow(p,
            followBtn(p) + `<button type="button" class="soc-btn warn" data-drop="${E(p.user_id)}">Remove</button>`)).join("")
        : `<p class="soc-none">Nobody is following you yet.</p>`;
    }

    setTimeout(() => {
      const sub = g("peoplesub");
      if(sub) sub.onclick = e => {
        const b = e.target.closest("button[data-p]"); if(!b) return;
        peopleList = b.dataset.p; paintClub();
      };
    }, 0);
    return picker + body;
  }

   
  

  const METRICS = [
    ["score",     "Collector score",   "Breadth, depth and rarity, weighted. Nothing financial goes into it."],
    ["unique",    "Releases",          "Distinct releases owned. A set box counts as none of its cars."],
    ["pieces",    "Pieces",            "Every copy counted, so five of one car is five pieces."],
    ["brands",    "Catalogues",        "How many different catalogues are represented."],
    ["marques",   "Marques",           "How many different makes of car."],
    ["ranges",    "Ranges completed",  "Ranges of five or more held in full."],
    ["rarity",    "Average rarity",    "Averaged over releases where rarity is established, and only with a sample of ten or more."],
    ["badges",    "Badges",            "Milestones the collection has passed."],
    ["value",     "Most valuable collections",
     "What the collection is estimated to be WORTH, at catalogue values. It is not what anybody spent, and this board is off until a collector turns it on for themselves."]
  ];
  const BRAND_METRICS = [
    ["unique",     "Releases held"],
    ["completion", "How complete"],
    ["pieces",     "Pieces"],
    ["rarity",     "Average rarity"]
  ];

  async function viewRank(){
    const brands = many(await rpc("ranking_brands", {}));
    const onBrand = !!st.rankBrand;
    const metrics = onBrand ? BRAND_METRICS : METRICS.map(m => [m[0], m[1]]);
    if(onBrand && !BRAND_METRICS.some(m => m[0] === st.rankMetric)) st.rankMetric = "unique";
    if(!onBrand && !METRICS.some(m => m[0] === st.rankMetric)) st.rankMetric = "score";

    const [board, mine, summary, published] = await Promise.all([
      rpc("leaderboard", { metric: st.rankMetric, brand_filter: st.rankBrand || null, limit_n: 50, offset_n: 0 }),
      rpc("my_rank", { metric: st.rankMetric, brand_filter: st.rankBrand || null }),
      rpc("my_ranking_summary", {}),
      

      rpc("catalogue_is_published", {})
    ]);
    const rows = many(board), me = one(mine), sum = one(summary);
    const catalogued = one(published) !== false;
    const chosen = METRICS.find(m => m[0] === st.rankMetric);

    let head = `<div class="soc-card"><div class="soc-row" style="gap:10px;flex-wrap:wrap">
      <select class="soc-sel" id="rankmetric">${metrics.map(([k, l]) =>
        `<option value="${k}"${k === st.rankMetric ? " selected" : ""}>${E(l)}</option>`).join("")}</select>
      <select class="soc-sel" id="rankbrand"><option value="">Every catalogue</option>${
        brands.map(b => `<option value="${E(b.brand)}"${b.brand === st.rankBrand ? " selected" : ""}>${
          E(b.brand)} (${Number(b.releases).toLocaleString()} releases)</option>`).join("")}</select>
    </div>${chosen && !onBrand ? `<p class="soc-note">${E(chosen[2])}</p>` : ""}</div>`;

    

    let standing = "";
    if(sum && sum.rankings_opt_in === false){
      standing = `<div class="soc-card"><b>You have taken yourself off the boards.</b>
        <p class="soc-note">Nothing about your collection is counted or shown on any board while that is
        so. You can put yourself back at any time.</p>
        <div class="soc-act" style="margin-top:10px"><button type="button" class="soc-btn pri" data-go="privacy">Open Privacy</button></div></div>`;
    }else if(me && me.rank != null){
      standing = `<div class="soc-card"><b>You are ${Number(me.rank).toLocaleString()} of ${
        Number(me.eligible).toLocaleString()}</b><i class="soc-note" style="display:block">on this board, with ${
        Number(me.value).toLocaleString()}.</i></div>`;
    }else if(st.rankMetric === "value" && sum && sum.value_ranking_opt_in === false){
      standing = `<div class="soc-card"><b>You are not on the value board.</b>
        <p class="soc-note">Being in the rankings is not consent to this one. It is a separate switch,
        because this board says something about money.</p>
        <div class="soc-act" style="margin-top:10px"><button type="button" class="soc-btn" data-go="privacy">Open Privacy</button></div></div>`;
    }else if(st.rankMetric === "value" && sum && sum.value_eligible === false){
      standing = `<div class="soc-card"><b>Not enough of your collection has a value yet.</b>
        <p class="soc-note">This board asks for a value on at least ten releases and on most of the
        collection, so that a figure covering a tenth of a shelf is not stood next to one covering all of it.</p></div>`;
    }else if(!rows.length && st.rankBrand){
      standing = `<div class="soc-card"><b>No board for this catalogue.</b>
        <p class="soc-note">A completion figure against a short list says more about the list than the
        collector, so a catalogue needs twenty-five releases on file before it gets a board.</p></div>`;
    }

    const cid = await creator();
    const list = rows.length
      ? `<div class="soc-card" style="padding:0">${rows.map(r => `
          <div class="soc-rank${r.is_me ? " me" : ""}">
            <span class="soc-pos">${Number(r.rank).toLocaleString()}</span>
            <button type="button" class="soc-id" data-open="${E(r.user_id)}">
              ${avatar(r, 34)}
              <span class="soc-grow"><b>${who(r)}${r.is_me ? " (you)" : ""}${
                r.user_id === cid ? '<span class="soc-chip-c">Creator</span>' : ""}</b>
              <i>${E(r.extra || "")}</i></span></button>
            <span class="soc-val">${Number(r.value).toLocaleString()}</span>
          </div>`).join("")}</div>`
      : catalogued
        ? `<p class="soc-none">Nobody is on this board yet.</p>`
        

        : `<p class="soc-none">The catalogue has not been published yet, so there is nothing
             for these boards to count against. They will fill once it is.</p>`;

    setTimeout(() => {
      const m = g("rankmetric"), b = g("rankbrand");
      if(m) m.onchange = () => { st.rankMetric = m.value; paintClub(); };
      if(b) b.onchange = () => { st.rankBrand = b.value; paintClub(); };
    }, 0);

    return head + standing + list + `<p class="soc-note">A board shows a total and nothing else.
      A collector can stand at the top of one with a collection nobody can read: the boards are
      built from figures the server works out, never by reading anybody's collection into anybody's
      browser, and a place on a board is not a way into a shelf. Anyone who would rather not appear
      can say so in Privacy.</p>`;
  }

   
  

  const ACT = {
    added_car:      d => "added " + (d.car_number || "a car"),
    added_showcase: () => "changed their showcase",
    earned_badge:   d => "earned " + ((d.meta && d.meta.badge) ? "the " + d.meta.badge + " badge" : "a badge"),
    completed_range:d => "completed " + ((d.meta && d.meta.range) ? d.meta.range : "a range"),
    milestone:      d => "passed a milestone",
    looking_for:    d => "is looking for " + (d.car_number || "a car"),
    spare:          d => "has a spare " + (d.car_number || "car")
  };
  const FEED_SCOPES = [["all","Everyone you know"],["friends","Friends"],["following","Following"],["mine","You"]];

  async function viewFeed(){
    const rows = many(await rpc("activity_feed", { limit_n: 60, offset_n: 0, scope: feedScope }));
    const picker = `<div class="soc-sub" id="feedsub" style="border:0;padding:0;margin:0 0 14px">${
      FEED_SCOPES.map(([k, l]) => `<button type="button" data-f="${k}"${k === feedScope ? ' class="on"' : ""}>${E(l)}</button>`).join("")}</div>`;
    setTimeout(() => {
      const sub = g("feedsub");
      if(sub) sub.onclick = e => {
        const b = e.target.closest("button[data-f]"); if(!b) return;
        feedScope = b.dataset.f; paintClub();
      };
    }, 0);
    if(!rows.length){
      return picker + `<p class="soc-none">Nothing here yet. You see your own, and somebody
        else's only where they chose to share it. Following somebody does not show you
        what they keep for friends.</p>`;
    }
    return picker + `<div class="soc-card" style="padding:4px 16px">${rows.map(r => {
      const line = (ACT[r.kind] || (d => String(d.kind).replace(/_/g, " ")))(r);
      const num = r.car_number ? String(r.car_number) : "";
      return `<div class="soc-set">
        <button type="button" class="soc-id" data-open="${E(r.user_id)}" style="flex:none;gap:9px">
          ${avatar(r, 32)}<span class="soc-grow"><b>${who(r)}${r.is_me ? " (you)" : ""}</b></span></button>
        <span class="soc-grow"><i>${E(line)}${
          num ? ` · <button type="button" class="soc-link" data-car="${E(num)}">open</button>` : ""
        } · ${E(ago(r.created_at))}</i></span></div>`;
    }).join("")}</div>`;
  }

   
  

  const SWITCHES = [
    ["rankings_opt_in", "Show me in the community rankings",
     "Your totals are counted and your name can appear on a board. Nothing about a particular car goes with them, and a board never opens a collection: a collector can be first on it with a collection nobody can read.",
     true],
    ["value_ranking_opt_in", "Include me in Most Valuable Collections",
     "A separate choice on purpose, and off until you make it. That board is about what a collection is estimated to be WORTH. It is never what you paid, and nobody sees a price you entered.",
     false]
  ];
  const CHOICES = [
    ["collection_visibility", "Who can see my collection",
     [["private","Only me"],["friends","Friends"],["public","Any signed-in collector"]]],
    ["wishlist_visibility", "Who can see my want list",
     [["private","Only me"],["friends","Friends"],["public","Any signed-in collector"]]],
    ["activity_visibility", "Who can see what I have been adding",
     [["private","Only me"],["friends","Friends"],["followers","People who follow me"]]]
  ];

  async function myPrivacy(){
    const rows = await AUTH.restJSON("/user_privacy?select=*&limit=1", { method:"GET" });
    return (Array.isArray(rows) ? rows[0] : rows) || {};
  }

  async function viewPrivacy(){
    const p = await myPrivacy();
    const blocks = many(await rpc("my_blocks", {}));
    let h = `<p class="soc-h">Who can see what</p>`;
    h += `<div class="soc-card">` + CHOICES.map(([k, label, opts]) =>
      `<div class="soc-set"><span class="soc-grow"><b>${E(label)}</b></span>
        <span class="soc-act"><select class="soc-sel" data-set="${k}">${opts.map(([v, l]) =>
          `<option value="${v}"${(p[k] || "private") === v ? " selected" : ""}>${E(l)}</option>`).join("")}</select></span></div>`).join("") + `</div>`;
    h += `<p class="soc-note">"Any signed-in collector" means the people who have an account
      here. Nothing on these screens is served to the open internet, and nothing at all is
      served to somebody who is not signed in. Turning your activity to "Only me" also
      deletes the activity already recorded, rather than merely hiding it.</p>`;
    h += `<p class="soc-h">Community rankings</p>`;
    h += `<div class="soc-card">` + SWITCHES.map(([k, label, note]) =>
      `<div class="soc-set"><span class="soc-grow"><b>${E(label)}</b><i>${E(note)}</i></span>
        <span class="soc-act"><button type="button" class="soc-btn${p[k] ? " pri" : ""}" data-flip="${k}"
          aria-pressed="${p[k] ? "true" : "false"}">${p[k] ? "On" : "Off"}</button></span></div>`).join("") + `</div>`;
    h += `<p class="soc-h">Your profile</p>`;
    h += `<p class="soc-note">Your name, handle and picture can be found by any other collector,
      and there is no setting that hides you from the community while you are part of it.
      If somebody is bothering you, block them: that closes every route between you, in
      both directions, and ends any friendship and any following either way.</p>`;
    h += `<p class="soc-h">Blocked</p>`;
    h += blocks.length
      ? blocks.map(b => personRow(b, `<button type="button" class="soc-btn" data-unblock="${E(b.user_id)}">Unblock</button>`)).join("")
      : `<p class="soc-none">You have not blocked anybody.</p>`;
    h += `<p class="soc-note">Unblocking does not put a friendship or a follow back: those
      were ended, and getting one back is somebody asking again.</p>`;

    setTimeout(() => {
      const host = g("clubbody"); if(!host) return;
      host.querySelectorAll("[data-flip]").forEach(b => {
        b.onclick = async () => {
          b.disabled = true;
          try{
            const cur = await myPrivacy();
            const next = Object.assign({}, cur); next[b.dataset.flip] = !cur[b.dataset.flip];
            await savePrivacy(next);
            say(next[b.dataset.flip] ? "Turned on." : "Turned off.");
          }catch(e){ say(e.message || String(e), "bad"); }
          paintClub();
        };
      });
      host.querySelectorAll("[data-set]").forEach(sel => {
        sel.onchange = async () => {
          try{
            const cur = await myPrivacy();
            const next = Object.assign({}, cur); next[sel.dataset.set] = sel.value;
            await savePrivacy(next);
            say("Saved.");
          }catch(e){ say(e.message || String(e), "bad"); }
          paintClub();
        };
      });
    }, 0);
    return h;
  }

  

  function savePrivacy(p){
    return rpc("set_privacy", {
      collection: p.collection_visibility || "private",
      wishlist:   p.wishlist_visibility   || "private",
      activity:   p.activity_visibility   || "private",
      rankings:   p.rankings_opt_in !== false,
      value_rank: !!p.value_ranking_opt_in
    });
  }

  

  function ensureSheet(){
    if(g("socmask")) return;
    const wrap = document.createElement("div");
    wrap.className = "sheetmask"; wrap.id = "socmask"; wrap.hidden = true;
    wrap.innerHTML = `<div class="sheet" id="socsheet" role="dialog" aria-modal="true"
        aria-label="A collector" tabindex="-1">
      <div class="sheethead"><b id="soctitle">Collector</b>
        <button class="iconbtn" id="socx" type="button">Close</button></div>
      <div class="sheetbody" id="socbody"></div></div>`;
    document.body.appendChild(wrap);
    g("socx").onclick = () => closeSheet("soc");
    wrap.onclick = e => { if(e.target === wrap) closeSheet("soc"); };
  }

  

  const PAGE_N = 500, PAGE_MAX = 40;
  async function allPages(fn, id, args){
    const sizeFn = fn === "view_wishlist" ? "wishlist_size" : "collection_size";
    let total = null;
    try { total = one(await rpc(sizeFn, { owner: id })); } catch(e) { total = null; }
    if(total && typeof total === "object") total = total.collection_size ?? total.wishlist_size ?? null;
    const out = [];
    for(let page = 0; page < PAGE_MAX; page++){
      const got = many(await rpc(fn, Object.assign({}, args, { limit_n: PAGE_N, offset_n: page * PAGE_N })));
      out.push.apply(out, got);
      if(got.length < PAGE_N) break;                  
      if(total != null && out.length >= total) break;
    }
    return out;
  }

  

  const SHOW_ALL = new Set();
  

  let LAST = null;

  function drawCollector(){
    if(!LAST) return;
    g("socbody").innerHTML = collectorHtml(LAST.card, LAST.coll, LAST.wish, LAST.show, LAST.cmp);
  }

  async function openCollector(id){
    ensureSheet();
    g("soctitle").textContent = "Collector";
    g("socbody").innerHTML = `<p class="soc-none">Loading.</p>`;
    openSheet("soc");
    try{
      const card = one(await rpc("collector_card", { owner: id }));
      if(!card){
        g("socbody").innerHTML = `<p class="soc-none">This collector's page is not open to you.
          A collector is findable and readable only where they chose to be.</p>`;
        return;
      }
      g("soctitle").textContent = (card.display_name || card.username || "Collector");
      const [coll, wish, show, cmp] = await Promise.all([
        card.collection_visible ? allPages("view_collection", id,
                                    { owner: id, brand_filter: null }) : Promise.resolve([]),
        card.wishlist_visible   ? allPages("view_wishlist", id,
                                    { owner: id }) : Promise.resolve([]),
        rpc("view_showcase", { owner: id }),
        card.is_self ? Promise.resolve(null) : rpc("compare_summary", { other: id })
      ]);
       
      if(card.is_creator) g("soctitle").textContent += " · Creator";
      LAST = { id: id, card: card, coll: many(coll), wish: many(wish),
               show: many(show), cmp: one(cmp) };
      drawCollector();
    }catch(e){
      g("socbody").innerHTML = `<div class="soc-card"><b>That did not load.</b>
        <p class="soc-note">${E(e.message || String(e))}</p></div>`;
    }
  }

  

  function titleOf(n){
    try{
      if(typeof DATA !== "undefined" && Array.isArray(DATA)){
        const d = DATA.find(x => x && x.n === n);
        if(d && d.t) return d.t;
      }
    }catch(_){}
    return "";
  }
  function numRow(n, extra){
    const t = titleOf(n);
    return `<div class="soc-set"><span class="soc-grow"><b>${E(t || n)}</b>
      <i>${E(t ? n : "")}${extra ? (t ? " · " : "") + E(extra) : ""}</i></span>
      <span class="soc-act"><button type="button" class="soc-btn" data-car="${E(n)}">Open</button></span></div>`;
  }

  function collectorHtml(c, coll, wish, show, cmp){
    let h = `<div class="soc-row" style="margin:0 0 14px;align-items:flex-start">${avatar(c, 56)}
      <span class="soc-grow"><b style="font-size:17px">${who(c)}${creatorChip(c)}</b>
      <i>${handle(c)}${c.collector_since ? (handle(c) ? " · " : "") + "collecting since " + E(String(c.collector_since).slice(0,4)) : ""}</i>
      <i style="margin-top:4px">
        <button type="button" class="soc-link" data-people="followers" data-of="${E(c.user_id)}"><b>${Number(c.followers||0).toLocaleString()}</b> followers</button>
        · <button type="button" class="soc-link" data-people="following" data-of="${E(c.user_id)}"><b>${Number(c.following||0).toLocaleString()}</b> following</button>
        ${c.follows_me && !c.is_self ? ' · follows you' : ""}</i></span></div>`;
    if(c.bio) h += `<p class="soc-note" style="margin:0 0 14px">${E(c.bio)}</p>`;
    if(c.favourite_brands && c.favourite_brands.length)
      h += `<p style="margin:0 0 14px">${c.favourite_brands.map(b => `<span class="soc-pill">${E(b)}</span>`).join("")}</p>`;

    if(!c.is_self){
       
      h += `<div class="soc-act" style="margin:0 0 16px">`
         + followBtn(c) + friendBtn(c)
         + (c.friend_state === "friends"
            ? `<button type="button" class="soc-btn" data-compare="${E(c.user_id)}">Compare collections</button>
               <button type="button" class="soc-btn warn" data-unfriend="${E(c.user_id)}">Remove friend</button>` : "")
         + `<button type="button" class="soc-btn warn" data-block="${E(c.user_id)}">Block</button></div>`;
    }

    h += `<div class="soc-card"><div class="soc-row" style="gap:18px;flex-wrap:wrap">
      ${[["unique_releases","releases"],["physical_pieces","pieces"],["on_the_way","on the way"],
         ["brands_collected","catalogues"],["marques_collected","marques"],["badges","badges"]]
        .map(([k, l]) => `<span><b style="font-size:18px">${Number(c[k] || 0).toLocaleString()}</b>
          <i style="display:block;font-style:normal;color:var(--tx2);font-size:12px">${l}</i></span>`).join("")}
    </div></div>`;

    if(cmp){
      h += `<p class="soc-h">You and them</p><div class="soc-card"><div class="soc-row" style="gap:18px;flex-wrap:wrap">
        ${[["in_both","both have"],["only_mine","only you"],["only_theirs","only them"],
           ["my_wants_they_own","they own, you want"],["their_spares_i_want","their spares you want"]]
          .map(([k, l]) => `<span><b style="font-size:18px">${Number(cmp[k] || 0).toLocaleString()}</b>
            <i style="display:block;font-style:normal;color:var(--tx2);font-size:12px">${l}</i></span>`).join("")}
      </div>${cmp.shared_brands && cmp.shared_brands.length
        ? `<p class="soc-note">Both collect ${cmp.shared_brands.map(b => E(b)).join(", ")}.</p>` : ""}</div>`;
    }

    if(show.length){
      h += `<p class="soc-h">Their showcase</p><div class="soc-card" style="padding:4px 16px">${
        show.map(s2 => numRow(s2.car_number, s2.note || "")).join("")}</div>`;
    }

    

    h += `<p class="soc-h">Collection</p>`;
    if(!c.collection_visible){
      h += `<p class="soc-none">${
        c.collection_privacy === "private"
          ? "Private collection. Only " + who(c) + " can see what is on these shelves, and being friends or following does not change that."
          : c.friend_state === "friends"
            ? "Private collection."
            : "Kept for friends. Ask, and they decide."}</p>`;
    }else if(!coll.length){
      h += `<p class="soc-none">Nothing on the shelf yet.</p>`;
    }else{
      

      const SHOWN = SHOW_ALL.has(c.user_id) ? coll.length : 200;
      h += `<div class="soc-card" style="padding:4px 16px">${coll.slice(0, SHOWN).map(r =>
        numRow(r.car_number, [r.qty > 1 ? r.qty + " copies" : "", r.condition || "", r.spare ? "spare" : ""]
          .filter(Boolean).join(" · "))).join("")}</div>`;
      if(coll.length > SHOWN)
        h += `<p class="soc-note">Showing the first ${SHOWN.toLocaleString()} of
          ${coll.length.toLocaleString()}.
          <button type="button" class="soc-btn" data-showall="${E(c.user_id)}">Show all
          ${coll.length.toLocaleString()}</button></p>`;
      else if(coll.length > 200)
        h += `<p class="soc-note">All ${coll.length.toLocaleString()} of them.</p>`;
      h += `<p class="soc-note">What a collector paid, where they bought it and anything they wrote for
        themselves are not here, and are not in what the server sent.</p>`;
    }

    h += `<p class="soc-h">Want list</p>`;
    if(!c.wishlist_visible){
      h += `<p class="soc-none">${c.friend_state === "friends"
        ? "Kept to themselves."
        : "Kept for friends."}</p>`;
    }else if(!wish.length){
      h += `<p class="soc-none">Nothing on the want list.</p>`;
    }else{
      const WSHOWN = SHOW_ALL.has(c.user_id) ? wish.length : Math.min(wish.length, 200);
      h += `<div class="soc-card" style="padding:4px 16px">${wish.slice(0, WSHOWN).map(r =>
        numRow(r.car_number, r.looking_for ? "actively looking" : "")).join("")}</div>`;
      if(wish.length > WSHOWN)
        h += `<p class="soc-note">Showing the first ${WSHOWN.toLocaleString()} of
          ${wish.length.toLocaleString()}.
          <button type="button" class="soc-btn" data-showall="${E(c.user_id)}">Show all</button></p>`;
    }
    return h;
  }

   
  async function openPeopleList(kind, owner){
    ensureSheet();
    g("soctitle").textContent = kind === "followers" ? "Followers" : "Following";
    g("socbody").innerHTML = `<p class="soc-none">Loading.</p>`;
    openSheet("soc");
    try{
      const rows = many(await rpc(kind === "followers" ? "followers_of" : "following_of",
                                 { owner: owner, limit_n: 100, offset_n: 0 }));
      g("socbody").innerHTML = rows.length
        ? rows.map(p => personRow(p)).join("")
        : `<p class="soc-none">${kind === "followers" ? "Nobody yet." : "Not following anybody yet."}</p>`;
    }catch(e){
      g("socbody").innerHTML = `<div class="soc-card"><b>That did not load.</b>
        <p class="soc-note">${E(e.message || String(e))}</p></div>`;
    }
  }

  async function openCompare(id){
    ensureSheet();
    g("soctitle").textContent = "Compare";
    g("socbody").innerHTML = `<p class="soc-none">Loading.</p>`;
    openSheet("soc");
    try{
      const [sum, rows] = await Promise.all([
        rpc("compare_summary", { other: id }),
        rpc("compare_collections", { other: id, limit_n: 400 })
      ]);
      const s = one(sum), list = many(rows);
      const bucket = k => list.filter(r => r.bucket === k);
      const sec = (title, k, note) => {
        const rs = bucket(k);
        return `<p class="soc-h">${E(title)}</p>${rs.length
          ? `<div class="soc-card" style="padding:4px 16px">${rs.slice(0, 150).map(r => numRow(r.car_number, "")).join("")}</div>`
          + (rs.length > 150 ? `<p class="soc-note">Showing the first 150 of ${rs.length.toLocaleString()}.</p>` : "")
          : `<p class="soc-none">${E(note)}</p>`}`;
      };
      g("socbody").innerHTML =
        (s ? `<div class="soc-card"><div class="soc-row" style="gap:18px;flex-wrap:wrap">
          ${[["in_both","both have"],["only_mine","only you"],["only_theirs","only them"]]
            .map(([k, l]) => `<span><b style="font-size:18px">${Number(s[k] || 0).toLocaleString()}</b>
              <i style="display:block;font-style:normal;color:var(--tx2);font-size:12px">${l}</i></span>`).join("")}
        </div></div>` : "")
        + sec("They own, you do not", "theirs", "Nothing they have that you do not.")
        + sec("You own, they do not", "mine", "Nothing you have that they do not.")
        + sec("Both of you", "both", "Nothing in common yet.");
    }catch(e){
      g("socbody").innerHTML = `<div class="soc-card"><b>That did not load.</b>
        <p class="soc-note">${E(e.message || String(e))}</p></div>`;
    }
  }

  

  const NEWS_TABS = [["you","For you"],["all","Everything"],["events","Events"]];
  const CATS = [["", "Everything"],["upcoming_release","Announced"],["new_release","Out now"],
                ["collaboration","Collaborations"],["exclusive","Exclusives"],
                ["event","At a show"],["brand","From the makers"]];

  function newsShell(){
    return `<div class="soc-wrap">
      <div class="soc-sub" id="newssub">${NEWS_TABS.map(([k, l]) =>
        `<button type="button" data-k="${k}"${k === st.newsScope ? ' class="on"' : ""}>${E(l)}</button>`).join("")}</div>
      <div id="newsbody"><p class="soc-none">Loading.</p></div>
    </div>`;
  }
  function drawNews(){
    const room = g("news"); if(!room) return;
    room.innerHTML = newsShell();
    g("newssub").onclick = e => {
      const b = e.target.closest("button[data-k]"); if(!b) return;
      st.newsScope = b.dataset.k;
      [...g("newssub").children].forEach(x => x.classList.toggle("on", x === b));
      paintNews();
    };
    paintNews();
  }
  function paintNews(){
    const body = g("newsbody"); if(!body) return;
    if(st.newsScope === "events") return into(body, viewEvents);
    return into(body, viewNews);
  }

  async function viewNews(){
    const rows = many(await rpc("news_feed", {
      scope: st.newsScope === "you" ? "you" : "all",
      category_filter: st.newsCat || null, brand_filter: null, limit_n: 40, offset_n: 0 }));
    const filter = `<div class="soc-card"><div class="soc-row" style="gap:10px;flex-wrap:wrap">
      <select class="soc-sel" id="newscat">${CATS.map(([k, l]) =>
        `<option value="${k}"${k === st.newsCat ? " selected" : ""}>${E(l)}</option>`).join("")}</select>
      </div></div>`;
    setTimeout(() => { const c = g("newscat"); if(c) c.onchange = () => { st.newsCat = c.value; paintNews(); }; }, 0);

    if(!rows.length){
      return filter + `<p class="soc-none">${st.newsScope === "you"
        ? "Nothing yet for the catalogues you collect. Everything shows what has come in across all of them."
        : "Nothing yet. The sources are read once a day."}</p>`;
    }
    return filter + rows.map(n => {
      const when = n.published_on ? day(n.published_on) : "";
      const rel = n.release_on
        ? (n.release_precision === "exact" ? "Out " + day(n.release_on)
           : "Expected " + day(n.release_on).replace(/^\d+ /, ""))
        : "";
      return `<div class="soc-card"><div class="soc-news">
        ${n.image_url ? `<img src="${E(n.image_url)}" alt="" loading="lazy" referrerpolicy="no-referrer">` : ""}
        <span class="soc-grow">
          <b style="display:block;font-size:15px;line-height:1.35">${E(n.headline)}</b>
          ${n.summary ? `<i style="display:block;font-style:normal;color:var(--tx2);font-size:13px;line-height:1.55;margin-top:5px">${E(n.summary)}</i>` : ""}
          <span style="display:block;margin-top:8px">
            ${(n.brands || []).map(b => `<span class="soc-pill">${E(b)}</span>`).join("")}
            ${rel ? `<span class="soc-pill">${E(rel)}</span>` : ""}
            ${n.mentions > 1 ? `<span class="soc-pill">${n.mentions} sources</span>` : ""}
          </span>
          ${(n.car_numbers || []).length
            ? `<span style="display:block;margin-top:8px" class="soc-act">${(n.car_numbers || []).slice(0,6).map(c =>
                `<button type="button" class="soc-btn" data-car="${E(c)}">${E(titleOf(c) || c)}</button>`).join("")}</span>` : ""}
          <i style="display:block;font-style:normal;color:var(--tx2);font-size:12px;margin-top:9px">
            ${when ? E(when) + " · " : ""}Reported by ${E(n.source_name || "a source")} ·
            <a href="${E(n.source_url)}" target="_blank" rel="noopener noreferrer nofollow">read it there</a></i>
        </span></div></div>`;
    }).join("") + `<p class="soc-note">MYMINI164 records what was announced and points at whoever reported it.
      The report itself belongs to them, so it is read on their page, not copied onto this one.</p>`;
  }

  async function viewEvents(){
    const rows = many(await rpc("events_feed", {
      when_filter: st.eventsWhen, country_filter: null, limit_n: 60, offset_n: 0 }));
    const picker = `<div class="soc-card"><div class="soc-row" style="gap:10px;flex-wrap:wrap">
      <select class="soc-sel" id="evwhen">${[["upcoming","Coming up"],["past","Been and gone"],
        ["saved","Ones you saved"],["all","All of them"]].map(([k, l]) =>
        `<option value="${k}"${k === st.eventsWhen ? " selected" : ""}>${E(l)}</option>`).join("")}</select>
      </div></div>`;
    setTimeout(() => { const w = g("evwhen"); if(w) w.onchange = () => { st.eventsWhen = w.value; paintNews(); }; }, 0);

    if(!rows.length) return picker + `<p class="soc-none">Nothing listed. An event appears here only once a
      real date has been published by the people running it; nothing is guessed from last year's.</p>`;

    return picker + rows.map(e2 => {
      const where = [e2.venue, e2.city, e2.country].filter(Boolean).map(E).join(", ");
      const when = e2.date_precision === "exact" ? span(e2.starts_on, e2.ends_on)
                 : e2.starts_on ? "Around " + day(e2.starts_on) : "Date not announced";
      return `<div class="soc-card"><div class="soc-row" style="align-items:flex-start">
        <span class="soc-grow">
          <b style="font-size:15px">${E(e2.name)}</b>
          <i style="display:block;font-style:normal;color:var(--tx2);font-size:13px;line-height:1.6;margin-top:4px">
            ${E(when)}${where ? " · " + where : ""}</i>
          ${e2.summary ? `<i style="display:block;font-style:normal;color:var(--tx2);font-size:12.5px;line-height:1.55;margin-top:6px">${E(e2.summary)}</i>` : ""}
          <span style="display:block;margin-top:8px">
            <span class="soc-pill">${E(e2.status === "ongoing" ? "On now" : e2.status === "completed" ? "Finished" : e2.status)}</span>
            ${(e2.brands || []).map(b => `<span class="soc-pill">${E(b)}</span>`).join("")}
          </span>
          <i style="display:block;font-style:normal;color:var(--tx2);font-size:12px;margin-top:9px">
            ${e2.official_url ? `<a href="${E(e2.official_url)}" target="_blank" rel="noopener noreferrer nofollow">the organisers</a> · ` : ""}
            <a href="${E(e2.source_url)}" target="_blank" rel="noopener noreferrer nofollow">where this was read</a></i>
        </span>
        <span class="soc-act"><button type="button" class="soc-btn${e2.saved ? " pri" : ""}"
          data-save="${E(e2.id)}" data-on="${e2.saved ? "1" : "0"}">${e2.saved ? "Saved" : "Save"}</button></span>
      </div></div>`;
    }).join("");
  }

  

  

  function openCarByNumber(n){
    try{
      if(typeof byNum !== "undefined" && byNum && typeof openCard === "function"){
        const d = byNum.get(n);
        if(d){
          closeSheet("soc");
          if(typeof current !== "undefined"){ current = [d]; openCard(0); return true; }
        }
      }
    }catch(_){}
    say("That car is not in this catalogue.");
    return false;
  }

  async function act(fn, done){
    try{
      const r = await fn();
      const said = (typeof r === "string") ? r : (r && r.length ? r[0] : r);
      if(typeof said === "string" && said !== "ok"){
        const FRIENDLY = {
          sent: "Asked. They decide.",
          already_sent: "You have already asked.",
          already_friends: "You are already friends.",
          accepted_theirs: "They had asked you, so that is now a friendship.",
          declined_recently: "That request could not be sent.",
          blocked: "That request could not be sent.",
          too_many: "That is a lot of requests for one day. Try again tomorrow.",
          invalid: "That cannot be done.",
          no_such_user: "No such collector.",
          not_yours: "That is not yours to answer.",
          not_pending: "That has already been answered.",
          no_such_request: "That request is gone.",
          friends: "You are friends.",
          following: "Following.",
          unfollowed: "No longer following.",
          not_a_collector: "That is not a collector's account.",
          removed: "Removed.",
          declined: "Declined.",
          cancelled: "Cancelled.",
          removed: "Removed.",
          blocked_ok: "Blocked.",
          unblocked: "Unblocked."
        };
        say(FRIENDLY[said] || said);
      }
      if(done) done();
    }catch(e){ say(e.message || String(e), "bad"); }
  }

  document.addEventListener("click", async e => {
    const b = e.target.closest("[data-open],[data-ask],[data-yes],[data-no],[data-cancel],[data-unfriend],"
      + "[data-block],[data-unblock],[data-compare],[data-car],[data-accept-from],[data-save],[data-go],"
      + "[data-follow],[data-unfollow],[data-drop],[data-people],[data-showall]");
    if(!b) return;
    const inOurs = b.closest("#club, #news, #socsheet");
    if(!inOurs) return;
    e.preventDefault();

    const d = b.dataset;
    

    if(d.showall){
      SHOW_ALL.add(d.showall);
      if(LAST && LAST.id === d.showall) drawCollector();    
      else await openCollector(d.showall);
      return;
    }
    if(d.car)        return void openCarByNumber(d.car);
    if(d.open)       return void openCollector(d.open);
    if(d.compare)    return void openCompare(d.compare);
    if(d.people)     return void openPeopleList(d.people, d.of);
    if(d.go){ clubTab = d.go;
      const sub = g("clubsub");
      if(sub) [...sub.children].forEach(x => x.classList.toggle("on", x.dataset.k === d.go));
      return void paintClub(); }

    b.disabled = true;
    const after = () => { if(g("socmask") && !g("socmask").hidden){   }
                          paintClub(); };
    

    if(d.follow || d.unfollow){
      const who2 = d.follow || d.unfollow;
      const on = !!d.follow;
      return void act(() => rpc(on ? "follow_user" : "unfollow_user", { target: who2 }), () => {
        b.disabled = false;
        b.textContent = on ? "Following" : "Follow";
        delete b.dataset.follow; delete b.dataset.unfollow;
        b.dataset[on ? "unfollow" : "follow"] = who2;
        b.classList.toggle("pri", false);
      });
    }
    if(d.drop)        return void act(() => rpc("remove_follower", { other: d.drop }), after);
    if(d.ask)         return void act(() => rpc("send_friend_request", { target: d.ask }), after);
    if(d.acceptFrom)  return void act(async () => {
        const rows = many(await rpc("my_friend_requests", {}));
        const r = rows.find(x => x.direction === "in" && x.other_id === d.acceptFrom);
        if(!r) return "That request is gone.";
        return rpc("accept_friend_request", { request_id: r.id });
      }, after);
    if(d.yes)      return void act(() => rpc("accept_friend_request", { request_id: d.yes }), after);
    if(d.no)       return void act(() => rpc("decline_friend_request", { request_id: d.no }), after);
    if(d.cancel)   return void act(() => rpc("cancel_friend_request", { request_id: d.cancel }), after);
    

    if(d.unfriend || d.block){
      if(b.dataset.sure !== "1"){
        b.dataset.sure = "1";
        b.dataset.was = b.textContent;
        b.textContent = d.block ? "Really block?" : "Really remove?";
        b.classList.add("warn");
        b.disabled = false;
        clearTimeout(b._sure);
        b._sure = setTimeout(() => {
          if(!b.isConnected) return;
          b.dataset.sure = "0"; b.textContent = b.dataset.was || "Remove";
        }, 6000);
        return;
      }
      clearTimeout(b._sure);
      if(d.unfriend)
        return void act(() => rpc("remove_friend", { other: d.unfriend }), () => { closeSheet("soc"); paintClub(); });
      return void act(() => rpc("block_user", { target: d.block }), () => { closeSheet("soc"); paintClub(); });
    }
    if(d.unblock)  return void act(() => rpc("unblock_user", { target: d.unblock }), after);
    if(d.save){
      const on = d.on === "1";
      return void act(async () => {
        if(on){
          await AUTH.rest("/event_saves?event_id=eq." + encodeURIComponent(d.save), { method:"DELETE" });
          return "Removed from your list.";
        }
        const me = AUTH.me && AUTH.me.id;
        await AUTH.rest("/event_saves", { method:"POST",
          headers:{ "Prefer":"resolution=ignore-duplicates" },
          body: JSON.stringify({ user_id: me, event_id: d.save }) });
        return "Saved.";
      }, () => paintNews());
    }
  }, false);

   
  EXTRA_VIEWS.club = { id:"club", eyebrow:"Community", draw: drawClub };
  EXTRA_VIEWS.news = { id:"news", eyebrow:"News and events", draw: drawNews };
  window.openCollector = openCollector;
})();


;window.__M164_APP_COMPLETE = true;
